  const total = Math.max(1, Math.ceil((cnt?.c || 0) / per));
  page = Math.max(0, Math.min(total - 1, page));
  const rows = await env.DB.prepare(`SELECT * FROM messages WHERE owner_id = ? AND is_deleted = 1 ${filter} ORDER BY sent_at DESC LIMIT ? OFFSET ?`).bind(ownerId, per, page * per).all().catch(() => ({ results: [] }));
  let out = `🗑 <b>УДАЛЁНКИ (${arg || "все"})</b> <i>(стр. ${page + 1}/${total}, всего ${cnt?.c || 0})</i>\n───────────────────────\n`;
