async function renderPeoplePage(env, entry, page, per) {
  const cnt = await env.DB.prepare("SELECT COUNT(*) AS c FROM authorized_users").bind().first().catch(() => null);
  const total = Math.max(1, Math.ceil((cnt?.c || 0) / per));
  page = Math.max(0, Math.min(total - 1, page));
  const rows = await env.DB.prepare("SELECT * FROM authorized_users ORDER BY added_at DESC LIMIT ? OFFSET ?").bind(per, page * per).all().catch(() => ({ results: [] }));
  const connSet = new Set(entry?.conns || []);
  let rep = `👥 <b>ПОЛЬЗОВАТЕЛИ БОТА</b> <i>(стр. ${page + 1}/${total})</i>\n───────────────────────\n`;
  if (page === 0) {
    rep += `👑 <b>Root-администраторы:</b>\n`;
    for (const id of ROOT_ADMINS) rep += `• <code>${id}</code>\n`;
    rep += `\n`;
  }
  rep += `👤 <b>Авторизованные (${cnt?.c || 0}):</b>\n`;
  if (!rows.results || !rows.results.length) rep += `<i>(пусто)</i>\n`;
  for (const u of (rows.results || [])) rep += `• <b>${escapeHtml(u.full_name || "")}</b> (<code>${u.user_id}</code>)${connSet.has(Number(u.user_id)) ? " 📱" : ""}\n`;
  if (page === 0 && entry) rep += `\n🚫 <b>В бане:</b> ${entry.bans ?? "?"} (/blocklist)\n`;
  rep += `\nДобавить: <code>/addpeople @ник</code> | Удалить: <code>/delpeople @ник</code>`;
  return { text: rep, page, total };
}

