async function renderLsPage(env, ownerId, page, per, filter) {
  const cap = Math.max(5, Math.min(50, per || 20));
  const pageNo = Math.max(0, page || 0);
  const needle = String(filter || "").trim().replace(/^@/, "");
  const like = `%${needle}%`;
  const useFilter = needle.length > 0;
  const where = `WHERE m.owner_id = ?` + (useFilter ? ` AND (CAST(m.user_id AS TEXT) LIKE ? OR IFNULL(m.username,'') LIKE ? OR IFNULL(m.full_name,'') LIKE ?)` : "");
  const binds = [ownerId];
  if (useFilter) binds.push(like, like, like);
  const total = await env.DB.prepare(`SELECT COUNT(*) AS c FROM (SELECT m.user_id FROM messages m ${where} GROUP BY m.user_id)`).bind(...binds).first().catch(() => ({ c: 0 }));
  const rows = await env.DB.prepare(
    `SELECT m.user_id AS user_id, m.username AS username, m.full_name AS full_name,
            COUNT(*) AS msgs, MAX(m.sent_at) AS last_at,
            SUM(CASE WHEN m.is_outgoing = 0 THEN 1 ELSE 0 END) AS incoming
     FROM messages m ${where}
     GROUP BY m.user_id
     ORDER BY msgs DESC, last_at DESC
     LIMIT ? OFFSET ?`
  ).bind(...binds, cap, pageNo * cap).all().catch(() => ({ results: [] }));
  const list = rows.results || [];
  const totalCount = Number(total?.c) || 0;
  const pages = Math.max(1, Math.ceil(totalCount / cap));
  let out = `\u{1F4CB} <b>Все, кто писал (стр. ${pageNo + 1}/${pages})</b>\n\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n`;
  if (useFilter) out += `\u{1F50E} Фильтр: <code>${escapeHtml(needle)}</code>\n`;
  if (!list.length) out += useFilter ? `\ud83d\ude41 Никого не нашёл по этому фильтру.\n` : `\ud83d\ude41 Сообщений пока нет.\n`;
  list.forEach((r, i) => {
    const uid = r.user_id || 0;
    const who = safeSlice(r.full_name || "Без имени", 36);
    const uname = r.username ? `@${safeSlice(String(r.username).replace(/^@/, ""), 32)}` : "без ника";
    const last = r.last_at ? new Date(Number(r.last_at) * 1000).toISOString().slice(0, 10) : "—";
    out += `${i + 1 + pageNo * cap}. <b>${escapeHtml(who)}</b>\n`;
    out += `    ${uname} \u2022 <code>${uid}</code>\n`;
    out += `    \ud83d\udcac ${Number(r.msgs) || 0} (входящих ${Number(r.incoming) || 0}) \u2022 ${escapeHtml(last)}\n`;
  });
  if (totalCount > 0) out += `\n<i>Всего уникальных: ${totalCount}</i>`;
  return { text: out, page: pageNo, total: pages };
}
async function pagerRender(env, ownerId, entry, page) {
  if (entry.mod === "read") return await renderReadPage(env, ownerId, entry.target, page, entry.per);
  if (entry.mod === "del") return await renderDeletedPage(env, ownerId, entry.arg, page, entry.per);
  if (entry.mod === "ed") return await renderEditsPage(env, entry.target, page, entry.per);
  if (entry.mod === "find") return await renderFindPage(env, ownerId, entry.q, page, entry.per);
  if (entry.mod === "people") return await renderPeoplePage(env, entry, page, entry.per);
  if (entry.mod === "banlist") return await renderBanlistPage(env, page, entry.per);
  if (entry.mod === "ls") return await renderLsPage(env, ownerId, page, entry.per, entry.filter);
  return { text: "❌ Неизвестный список.", page: 0, total: 1 };
}

