    await env.DB.prepare("INSERT OR REPLACE INTO afk (chat_id, user_id, user_name, reason, since) VALUES (?, ?, ?, ?, ?)")
      .bind(chatId, userId, String(userName || "").slice(0, 100), String(reason || "").slice(0, 200), Math.floor(Date.now() / 1000)).run();
