async function addKarma(env, chatId, userId, userName, delta) {
  try {
    await env.DB.prepare("INSERT INTO karma (chat_id, user_id, user_name, karma, updated_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT(chat_id, user_id) DO UPDATE SET karma = karma + ?, user_name = excluded.user_name, updated_at = excluded.updated_at")
      .bind(chatId, userId, String(userName || "").slice(0, 100), delta, Math.floor(Date.now() / 1000), delta).run();
    const r = await env.DB.prepare("SELECT karma FROM karma WHERE chat_id = ? AND user_id = ?").bind(chatId, userId).first();
    return r?.karma ?? delta;
  } catch { return null; }
}

function aiMemKey(ownerId, userId) {
  return ownerId + ":" + userId;
}

function aiMemGet(ownerId, userId) {
  return AI_MEM.get(aiMemKey(ownerId, userId)) || [];
}

function aiMemPush(ownerId, userId, role, content) {
  const k = aiMemKey(ownerId, userId);
  const arr = AI_MEM.get(k) || [];
  arr.push({ role, content: String(content || "").slice(0, 1500) });
  while (arr.length > 10) arr.shift();
  if (AI_MEM.size > 500) {
    const first = AI_MEM.keys().next().value;
    AI_MEM.delete(first);
  }
  AI_MEM.set(k, arr);
}

function aiMemClear(ownerId, userId) {
  AI_MEM.delete(aiMemKey(ownerId, userId));
}

const MARRY_PENDING = new Map();
const DUEL_STATE = new Map();

