async function getCoins(env, chatId, userId) {
  try {
    const r = await env.DB.prepare("SELECT coins FROM economy WHERE chat_id = ? AND user_id = ?").bind(chatId, userId).first();
    return r?.coins || 0;
  } catch { return 0; }
}

function todayStr() {
  return new Date().toISOString().slice(0, 10);
}

function yesterdayStr() {
  return new Date(Date.now() - 86400000).toISOString().slice(0, 10);
}

async function updateStreak(env, chatId, userId, userName) {
  try {
    const t = todayStr();
    const r = await env.DB.prepare("SELECT streak, last_day FROM streaks WHERE chat_id = ? AND user_id = ?").bind(chatId, userId).first();
    if (r?.last_day === t) return { streak: r.streak, renewed: false };
    const ns = r?.last_day === yesterdayStr() ? (r.streak + 1) : 1;
    await env.DB.prepare("INSERT INTO streaks (chat_id, user_id, user_name, streak, last_day) VALUES (?, ?, ?, ?, ?) ON CONFLICT(chat_id, user_id) DO UPDATE SET streak = excluded.streak, last_day = excluded.last_day, user_name = excluded.user_name")
      .bind(chatId, userId, String(userName || "").slice(0, 100), ns, t).run();
    return { streak: ns, renewed: true };
  } catch { return null; }
}

