const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Requested-With"
};

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      ...CORS_HEADERS
    }
  });
}

function escapeHtml(str) {
  if (!str) return "";
  return String(str).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function sanitizeSurrogates(text) {
  return String(text ?? "").replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?:[^\uD800-\uDBFF]|^)[\uDC00-\uDFFF]/g, (m) => (m.length > 1 ? m[0] + "�" : "�"));
}

function safeSlice(text, n) {
  const chars = [...String(text ?? "")];
  if (chars.length <= n) return chars.join("");
  return chars.slice(0, n).join("");
}

const CREDIT_MARKER = /Бот разработан/;

function hasCredit(text) {
  return CREDIT_MARKER.test(String(text || ""));
}

function withCredit(text) {
  const t = String(text || "");
  return hasCredit(t) ? t : t + MANDATORY_COPYRIGHT;
}

function withCreditEscaped(text) {
  const t = String(text || "");
  return hasCredit(t) ? escapeHtml(t) : escapeHtml(t) + MANDATORY_COPYRIGHT;
}

// Telegram allows ~30 messages/second. Everything the bot sends goes through this queue
// so bursts get spaced out, and a 429 is retried after the delay Telegram asks for.
const TG_SAFE_MS = 55;
let tgLastSend = 0;
let tgQueue = Promise.resolve();

function tgRetryAfterMs(err) {
  const m = String(err && (err.description || err.message) || "").match(/retry after (\d+)/i);
  if (m) return Math.min(60000, (parseInt(m[1], 10) || 5) * 1000);
  if (err && err.error_code === 429) return 5000;
  return null;
}

async function tgRawSend(fn) {
  const wait = tgLastSend + TG_SAFE_MS - Date.now();
  if (wait > 0) await sleep(wait);
  try {
    const r = await fn();
    tgLastSend = Date.now();
    return r;
  } catch (e) {
    const retry = tgRetryAfterMs(e);
    if (retry === null) throw e;
    tgLastSend = Date.now();
    console.error("telegram 429, waiting " + retry + "ms");
    await sleep(retry);
    return tgRawSend(fn);
  }
}

function tgSend(fn) {
  const next = tgQueue.then(() => tgRawSend(fn), () => tgRawSend(fn));
  // keep the chain alive even if this send fails
  tgQueue = next.then(() => {}, () => {});
  return next;
}

// drop a message the user can no longer see instead of shouting a raw 429 at them
function tgErrorText(e) {
  if (e && (e.error_code === 429 || /Too Many Requests|retry after/i.test(String(e.description || e.message)))) {
    return "⏳ Telegram не даёт отправить так быстро — сообщение слишком часто. Повтори через пару секунд.";
  }
  return null;
}

// Telegram rejects anything over 4096 chars, so long reports are sent in parts
function splitLongText(text, limit = 3800) {
  const out = [];
  let rest = String(text || "");
  if (!rest) return [""];
  while (rest.length > limit) {
    let cut = rest.lastIndexOf("\n", limit);
    if (cut < limit * 0.4) cut = rest.lastIndexOf(" ", limit);
    if (cut < limit * 0.4) cut = limit;
    out.push(rest.slice(0, cut).trimEnd());
    rest = rest.slice(cut).replace(/^\s+/, "");
  }
  out.push(rest);
  return out.filter((s, i) => s.length > 0 || i === 0);
}

// sends a long HTML report, splitting it and never failing silently
async function sendLongHtml(ctx, html, opts = {}) {
  const parts = splitLongText(html);
  let sent = 0;
  for (let i = 0; i < parts.length; i++) {
    const last = i === parts.length - 1;
    let text = parts[i];
    if (last && opts.credit !== false) text = withCredit(text);
    try {
      await tgSend(() => ctx.reply(text, { parse_mode: "HTML", link_preview_options: { is_disabled: true }, ...opts }));
      sent++;
    } catch (e) {
      const m = String(e && e.message || e);
      if (/can't parse entities|ParseEntity|unsupported start tag/i.test(m)) {
        try { await tgSend(() => ctx.reply(escapeHtml(parts[i]), { link_preview_options: { is_disabled: true }, ...opts })); sent++; continue; } catch (e2) { e = e2; }
      }
      const friendly = tgErrorText(e);
      if (friendly) {
        console.error("sendLongHtml rate limited:", m);
        try { await tgSend(() => ctx.reply(friendly, { parse_mode: "HTML" })); } catch {}
        return sent;
      }
      console.error("sendLongHtml part failed:", m);
      if (!sent) {
        try { await tgSend(() => ctx.reply("⚠️ Не смог отправить ответ: " + escapeHtml(m.slice(0, 150)), { parse_mode: "HTML" })); } catch {}
      }
    }
  }
  return sent;
}

function creditBlock() {
  return MANDATORY_COPYRIGHT;
}

function creditText(text) {
  return withCredit(text);
}

function creditCaption(text) {
  return withCredit(text);
}

function addCreditToInlineResult(result) {
  if (!result || typeof result !== "object") return result;
  const r = { ...result };
  const content = r.input_message_content;
  if (content && typeof content === "object" && typeof content.message_text === "string") {
    r.input_message_content = {
      ...content,
      message_text: content.parse_mode === "HTML" ? creditText(content.message_text) : `${content.message_text}${creditBlock()}`
    };
  }
  if (typeof r.caption === "string") {
    r.caption = r.parse_mode === "HTML" ? creditCaption(r.caption) : `${r.caption}${creditBlock()}`;
  }
  return r;
}

async function answerInlineWithCredit(ctx, results, options) {
  const list = (Array.isArray(results) ? results : [results]).filter(Boolean).map((r) => {
    const credited = addCreditToInlineResult(r);
    const content = credited?.input_message_content;
    if (content && typeof content.message_text === "string") {
      content.message_text = sanitizeSurrogates(content.message_text);
    }
    if (typeof credited?.caption === "string") credited.caption = sanitizeSurrogates(credited.caption);
    if (typeof credited?.title === "string") credited.title = sanitizeSurrogates(credited.title);
    if (typeof credited?.description === "string") credited.description = sanitizeSurrogates(credited.description);
    return credited;
  });
  return ctx.answerInlineQuery(list, options);
}

const CREDIT_TEXT_METHODS = new Set(["sendMessage", "editMessageText"]);
const CREDIT_CAPTION_METHODS = new Set([
  "sendPhoto",
  "sendVideo",
  "sendAudio",
  "sendDocument",
  "sendAnimation",
  "sendVoice",
  "sendVideoNote",
  "sendPaidMedia",
  "sendMediaGroup"
]);

function applyMandatoryCredit(bot) {
  bot.api.config.use(async (prev, method, payload, signal) => {
    if (payload && typeof payload === "object") {
      if (CREDIT_TEXT_METHODS.has(method) && typeof payload.text === "string" && payload.text.trim()) {
        payload.text = sanitizeSurrogates(withCredit(payload.text));
      }
      if (CREDIT_CAPTION_METHODS.has(method)) {
        if (typeof payload.caption === "string" && payload.caption.trim()) {
          payload.caption = sanitizeSurrogates(withCredit(payload.caption));
        }
        if (Array.isArray(payload.media) && payload.parse_mode === "HTML") {
          payload.media = payload.media.map(m => (typeof m?.caption === "string" && m.caption.trim() ? { ...m, caption: sanitizeSurrogates(withCredit(m.caption)) } : m));
        }
      }
    }
    return prev(method, payload, signal);
  });
}
const CRC_TABLE = (() => {
  let c; const t = [];
  for (let n = 0; n < 256; n++) {
    c = n;
    for (let k = 0; k < 8; k++) c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
    t[n] = c;
  }
  return t;
})();

function crc32(buf) {
  let crc = 0 ^ (-1);
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buf[i]) & 0xFF];
  return (crc ^ (-1)) >>> 0;
}

function createZip(files) {
  const localHeaders = [];
  const centralHeaders = [];
  let offset = 0;

  for (const f of files) {
    const nameBytes = new TextEncoder().encode(f.name);
    const dataBytes = f.data instanceof Uint8Array ? f.data : new TextEncoder().encode(f.data);
    const crc = crc32(dataBytes);
    const size = dataBytes.length;
    const d = f.date || new Date();
    const dosTime = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
    const dosDate = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();

    const local = new Uint8Array(30 + nameBytes.length + size);
    const lv = new DataView(local.buffer);
    lv.setUint32(0, 0x04034b50, true);
    lv.setUint16(4, 20, true);
    lv.setUint16(6, 0x0800, true);
    lv.setUint16(8, 0, true);
    lv.setUint16(10, dosTime, true);
    lv.setUint16(12, dosDate, true);
    lv.setUint32(14, crc, true);
    lv.setUint32(18, size, true);
    lv.setUint32(22, size, true);
    lv.setUint16(26, nameBytes.length, true);
    lv.setUint16(28, 0, true);
    local.set(nameBytes, 30);
    local.set(dataBytes, 30 + nameBytes.length);

    const central = new Uint8Array(46 + nameBytes.length);
    const cv = new DataView(central.buffer);
    cv.setUint32(0, 0x02014b50, true);
    cv.setUint16(4, 20, true);
    cv.setUint16(6, 20, true);
    cv.setUint16(8, 0x0800, true);
    cv.setUint16(10, 0, true);
    cv.setUint16(12, dosTime, true);
    cv.setUint16(14, dosDate, true);
    cv.setUint32(16, crc, true);
    cv.setUint32(20, size, true);
    cv.setUint32(24, size, true);
    cv.setUint16(28, nameBytes.length, true);
    cv.setUint16(30, 0, true);
    cv.setUint16(32, 0, true);
    cv.setUint16(34, 0, true);
    cv.setUint16(36, 0, true);
    cv.setUint32(38, 0, true);
    cv.setUint32(42, offset, true);
    central.set(nameBytes, 46);

    localHeaders.push(local);
    centralHeaders.push(central);
    offset += local.length;
  }

  const centralOffset = offset;
  let centralSize = 0;
  for (const c of centralHeaders) centralSize += c.length;

  const eocd = new Uint8Array(22);
  const ev = new DataView(eocd.buffer);
  ev.setUint32(0, 0x06054b50, true);
  ev.setUint16(4, 0, true);
  ev.setUint16(6, 0, true);
  ev.setUint16(8, files.length, true);
  ev.setUint16(10, files.length, true);
  ev.setUint32(12, centralSize, true);
  ev.setUint32(16, centralOffset, true);
  ev.setUint16(20, 0, true);

  const total = new Uint8Array(centralOffset + centralSize + 22);
  let pos = 0;
  for (const l of localHeaders) { total.set(l, pos); pos += l.length; }
  for (const c of centralHeaders) { total.set(c, pos); pos += c.length; }
  total.set(eocd, pos);
  return total;
}
