function arMinutesToHHMM(min) {
  const v = Math.max(0, Math.min(24 * 60 - 1, parseInt(min) || 0));
  return `${String(Math.floor(v / 60)).padStart(2, "0")}:${String(v % 60).padStart(2, "0")}`;
}

function arParseTime(input) {
  const raw = String(input || "").trim().toLowerCase();
  if (!raw) return null;
  const hm = raw.match(/^(\d{1,2})\s*[:.]\s*(\d{2})$/) || raw.match(/^(\d{1,2})\s*ч\s*(\d{2})$/) || raw.match(/^(\d{1,2})(\d{2})$/);
  if (hm) {
    const h = parseInt(hm[1], 10);
    const m = parseInt(hm[2], 10);
    if (h > 23 || m > 59) return null;
    return h * 60 + m;
  }
  const onlyHour = raw.match(/^(\d{1,2})$/);
  if (onlyHour) {
    const h = parseInt(onlyHour[1], 10);
    if (h > 23) return null;
    return h * 60;
  }
  return null;
}

function arParseDays(input) {
  const raw = String(input || "").trim().toLowerCase();
  if (!raw || raw === "all" || raw === "все" || raw === "365" || raw === "каждый") return [0, 1, 2, 3, 4, 5, 6];
  if (raw === "week" || raw === "weekdays" || raw === "пн-пт" || raw === "будни" || raw === "рабочие") return [1, 2, 3, 4, 5];
  if (raw === "выходные" || raw === "weekend" || raw === "сб-вс") return [0, 6];
  const out = new Set();
  const idx = { "вс": 0, "воскресенье": 0, "пн": 1, "понедельник": 1, "вт": 2, "вторник": 2, "ср": 3, "среда": 3, "чт": 4, "четверг": 4, "пт": 5, "пятница": 5, "сб": 6, "суббота": 6 };
  for (const token of raw.split(/[\s,+\-–]+/).filter(Boolean)) {
    if (/^\d$/.test(token)) {
      const n = parseInt(token, 10);
      if (n >= 0 && n <= 6) out.add(n);
      continue;
    }
    if (idx[token] !== undefined) out.add(idx[token]);
  }
  return out.size ? [...out].sort() : null;
}

function arDaysToText(days) {
  const list = Array.isArray(days) ? [...days].sort() : [1, 2, 3, 4, 5];
  if (list.length === 7) return "каждый день";
  if (list.join() === "1,2,3,4,5") return "Пн–Пт";
  if (list.join() === "0,6") return "Сб–Вс";
  return list.map((d) => AR_DAY_NAMES[d]).join(", ");
}

function arNowMinutes() {
  const now = new Date(new Date().toLocaleString("en-US", { timeZone: "Europe/Moscow" }));
  return { day: now.getDay(), minutes: now.getHours() * 60 + now.getMinutes() };
}

function arResolveDays(value) {
  if (Array.isArray(value)) return value;
  const parsed = arParseDays(value ?? "1,2,3,4,5");
  return parsed || [1, 2, 3, 4, 5];
}

function arIsWithinWork(cfg, nowArg) {
  const now = nowArg || arNowMinutes();
  const days = arResolveDays(cfg.work_days);
  if (!days.includes(now.day)) return { ok: false, reason: "day" };
  const start = Number.isFinite(Number(cfg.work_start)) ? Number(cfg.work_start) : 300;
  const end = Number.isFinite(Number(cfg.work_end)) ? Number(cfg.work_end) : 1200;
  if (start === end) return { ok: true, reason: "always", start, end };
  if (start < end) {
    return now.minutes >= start && now.minutes < end ? { ok: true, reason: "window", start, end } : { ok: false, reason: "time", start, end };
  }
  const overnight = now.minutes >= start || now.minutes < end;
  return overnight ? { ok: true, reason: "overnight", start, end } : { ok: false, reason: "time", start, end };
}

function arWorkStatusText(cfg, nowArg) {
  const now = nowArg || arNowMinutes();
  const state = arIsWithinWork(cfg, now);
  const span = `${arMinutesToHHMM(state.start ?? arResolveStart(cfg))}–${arMinutesToHHMM(state.end ?? arResolveEnd(cfg))}`;
  const days = arDaysToText(arResolveDays(cfg.work_days));
  if (state.ok) return { emoji: "🔒", status: "Занят", extra: state.reason === "overnight" ? `ночная смена ${span}` : `работаю ${span}`, span, days, now };
  if (state.reason === "day") return { emoji: "🏖", status: "Выходной", extra: `${days} — выходной`, span, days, now };
  return { emoji: "💬", status: "Свободен", extra: `работаю ${span} (${days})`, span, days, now };
}

function arResolveStart(cfg) {
  return Number.isFinite(Number(cfg.work_start)) ? Number(cfg.work_start) : 300;
}

function arResolveEnd(cfg) {
  return Number.isFinite(Number(cfg.work_end)) ? Number(cfg.work_end) : 1200;
}

