function buildAutoReplyText(cfg, nowArg) {
  const info = arWorkStatusText(cfg, nowArg);
  const custom = cfg.custom_reply ? String(cfg.custom_reply).trim() : "";

  if (!cfg.ar_variety && custom) {
    return `${info.emoji} <b>Статус:</b> ${info.status}\n${custom}`;
  }

  if (custom) {
    const pool = [custom, ...AR_QUICK_REPLIES.map((t) => `${custom}\n\n<i>${t}</i>`)];
    return `${info.emoji} <b>Статус:</b> ${info.status}\n${pool[Math.floor(Math.random() * pool.length)]}`;
  }

  if (!cfg.ar_variety) {
    return `${info.emoji} <b>Статус:</b> ${info.status}\n<i>Сейчас не на связи — отвечу попозже.</i>`;
  }

  const variants = [
    `${info.emoji} <b>Статус:</b> ${info.status}\n<i>${info.extra}</i>`,
    `${info.emoji} <b>Статус:</b> ${info.status}\n<i>${info.extra}</i>\n\nОтвечу, как освобожусь.`,
    `${info.emoji} <b>Статус:</b> ${info.status}\n<i>${info.extra}</i>\n\nСейчас не на связи. Напишите позже, пожалуйста.`,
    `${info.emoji} <b>Статус:</b> ${info.status}\n⏰ ${info.extra}`,
    `<b>Статус:</b> ${info.status}\n${info.extra}`,
    `${info.emoji} <b>Статус:</b> ${info.status} — ${info.extra}`
  ];
  return variants[Math.floor(Math.random() * variants.length)];
}

