function invalidateAllowedCache() {
  ALLOWED_CACHE = new Set();
  LAST_ALLOWED_FETCH = 0;
}

async function isBanned(env, userId) {
  if (!userId) return false;
  try {
    const r = await env.DB.prepare("SELECT 1 FROM banned_users WHERE user_id = ?").bind(Number(userId)).first();
    return !!r;
  } catch { return false; }
}

async function isAllowed(env, userId) {
  if (!userId) return false;
  const numId = Number(userId);
  if (isNaN(numId) || numId === 0) return false;

  try {
    const b = await env.DB.prepare("SELECT 1 FROM banned_users WHERE user_id = ?").bind(numId).first();
    if (b) return false;
  } catch {}

  if (ROOT_ADMINS.includes(numId)) return true;

  const now = Date.now();
  if (ALLOWED_CACHE.size > 0 && now - LAST_ALLOWED_FETCH < 30000) {
    return ALLOWED_CACHE.has(numId);
  }

  const ids = new Set(ROOT_ADMINS.map(Number));
  try {
    const rows = await env.DB.prepare("SELECT user_id FROM authorized_users").all();
    if (rows.results) {
      for (const r of rows.results) ids.add(Number(r.user_id));
    }
    const connRows = await env.DB.prepare("SELECT user_id FROM connections WHERE is_active = 1 OR is_active IS NULL").all();
    if (connRows.results) {
      for (const r of connRows.results) {
        try {
          const bb = await env.DB.prepare("SELECT 1 FROM banned_users WHERE user_id = ?").bind(Number(r.user_id)).first();
          if (bb) continue;
        } catch {}
        ids.add(Number(r.user_id));
      }
    }
  } catch {}

  ALLOWED_CACHE = ids;
  LAST_ALLOWED_FETCH = now;
  return ids.has(numId);
}

async function getUserSettings(env, userId) {
  const def = {
    user_id: userId,
    auto_reply: 0,
    cooldown_sec: 1800,
    notify_deleted: 1,
    notify_edited: 1,
    notify_new_user: 0,
    reply_mode: "blacklist",
    custom_reply: null,
    troll_text: null,
    work_start: 300,
    work_end: 1200,
    work_days: "1,2,3,4,5",
    ar_variety: 1
  };

  try {
    let s = await env.DB.prepare("SELECT * FROM settings WHERE user_id = ?").bind(userId).first();
    if (!s) {
      await env.DB.prepare(`
        INSERT OR IGNORE INTO settings (user_id, auto_reply, cooldown_sec, notify_deleted, notify_edited, notify_new_user, reply_mode, work_start, work_end, work_days, ar_variety)
        VALUES (?, 0, 1800, 1, 1, 0, 'blacklist', 300, 1200, '1,2,3,4,5', 1)
      `).bind(userId).run();
      return def;
    }
    const merged = { ...def, ...s };
    merged.work_start = Number.isFinite(Number(s.work_start)) ? Number(s.work_start) : 300;
    merged.work_end = Number.isFinite(Number(s.work_end)) ? Number(s.work_end) : 1200;
    merged.ar_variety = s.ar_variety === null || s.ar_variety === undefined ? 1 : Number(s.ar_variety);
    merged.cooldown_sec = Number(s.cooldown_sec) || 1800;
    merged.work_days = s.work_days || "1,2,3,4,5";
    return merged;
  } catch {
    return def;
  }
}

async function resolveTargetUser(env, ownerId, query) {
  if (!query) return null;
  const clean = query.replace("@", "").trim();

  if (/^-?\d+$/.test(clean)) {
    const id = parseInt(clean);
    const u = await env.DB.prepare("SELECT user_id, full_name, username FROM users WHERE user_id = ?").bind(id).first();
    if (u) return u;
    const m = await env.DB.prepare("SELECT user_id, full_name, username FROM messages WHERE user_id = ? OR chat_id = ? LIMIT 1").bind(id, id).first();
    if (m) return { user_id: id, full_name: m.full_name || `User ${id}`, username: m.username || "" };
    return { user_id: id, full_name: `User ${id}`, username: "" };
  }

  let u = await env.DB.prepare("SELECT user_id, full_name, username FROM users WHERE username = ? COLLATE NOCASE").bind(clean).first();
  if (u) return u;

  let m = await env.DB.prepare("SELECT user_id, full_name, username FROM messages WHERE username = ? COLLATE NOCASE LIMIT 1").bind(clean).first();
  if (m) return { user_id: m.user_id, full_name: m.full_name, username: m.username };

  u = await env.DB.prepare("SELECT user_id, full_name, username FROM users WHERE username LIKE ? OR full_name LIKE ? LIMIT 1").bind(`%${clean}%`, `%${clean}%`).first();
  if (u) return u;

  m = await env.DB.prepare("SELECT user_id, full_name, username FROM messages WHERE username LIKE ? OR full_name LIKE ? LIMIT 1").bind(`%${clean}%`, `%${clean}%`).first();
  if (m) return { user_id: m.user_id, full_name: m.full_name, username: m.username };

  return null;
}

async function transcribeAudio(env, bot, fileId) {
  if (!env.AI) return null;
  try {
    const file = await bot.api.getFile(fileId);
    if (!file.file_path) return null;
    const fileUrl = `https://api.telegram.org/file/bot${env.BOT_TOKEN}/${file.file_path}`;
    const res = await fetch(fileUrl);
    if (!res.ok) {
      await discardBody(res);
      return null;
    }
    const blob = await res.arrayBuffer();
    const result = await env.AI.run("@cf/openai/whisper", {
      audio: [...new Uint8Array(blob)]
    });
    return result?.text?.trim() || null;
  } catch (err) {
    return null;
  }
}

function getAccountAge(userId) {
  if (userId < 150000000) return "2013–2015";
  if (userId < 450000000) return "2016–2017";
  if (userId < 800000000) return "2018–2019";
  if (userId < 1500000000) return "2020–2021";
  if (userId < 5500000000) return "2021–2022";
  if (userId < 6800000000) return "2023";
  if (userId < 7500000000) return "2024";
  return "2025–2026";
}

function formatDelta(sec) {
  if (sec < 60) return `${sec} сек.`;
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  if (m < 60) return `${m} мин. ${s} сек.`;
  const h = Math.floor(m / 60);
  const remM = m % 60;
  return `${h} ч. ${remM} мин.`;
}

function buildSettingsKeyboard(cfg) {
  const kb = new InlineKeyboard();
  const arState = cfg.auto_reply ? "🟢 ВКЛ" : "🔴 ВЫКЛ";
  const modeText = cfg.reply_mode === "whitelist" ? "⚪ Белый список" : "⚫ Все, кроме чёрного";
  const delState = cfg.notify_deleted ? "🟢 ВКЛ" : "🔴 ВЫКЛ";
  const editState = cfg.notify_edited ? "🟢 ВКЛ" : "🔴 ВЫКЛ";

  kb.text(`Автоответчик: ${arState}`, "toggle_ar").row();
  kb.text(`Фильтр автоответа: ${modeText}`, "toggle_mode").row();
  kb.text("Кулдаун: 15м", "cd_900").text("30м", "cd_1800").text("1ч", "cd_3600").text("3ч", "cd_10800").row();
  kb.text(`Удалёнки: ${delState}`, "toggle_del").text(`Правки: ${editState}`, "toggle_edit").row();
  kb.text("🔄 Обновить статус", "refresh_settings");

  return kb;
}
