// Commands the AI is allowed to trigger. Never moderation, never data-destroying.
const AI_RUN_ALLOW = new Set([
  "/soundcloud", "/sc", "/music", "/yt", "/shorts", "/tiktok", "/search", "/news", "/wiki", "/dict", "/tr",
  "/weather", "/city", "/crypto", "/rate", "/time", "/calc", "/convert", "/8ball", "/joke", "/fact", "/quote",
  "/proverb", "/riddle", "/anagram", "/excuse", "/horo", "/dream", "/mood", "/bio", "/advice", "/bored",
  "/dox", "/info", "/aiham", "/burn", "/bold", "/italic", "/mono", "/under", "/leet", "/kawaii", "/tsundere",
  "/yandere", "/spoiler", "/shout", "/reverse", "/dns", "/passgen", "/qr", "/holiday", "/ruyi", "/coin"
]);

const AI_RUN_RE = /\/run\s+(\/[a-z0-9_]+)((?:\s+[^\n`<>*|]+)?)/i;

function extractAiRunCommand(text) {
  const m = String(text || "").match(AI_RUN_RE);
  if (!m) return null;
  const word = m[1].toLowerCase();
  if (!AI_RUN_ALLOW.has(word)) return null;
  const arg = (m[2] || "").trim().replace(/\s+/g, " ").slice(0, 200);
  return arg ? word + " " + arg : word;
}

// Runs a command the AI asked for, inside the same chat (and the same business connection).
let AI_RUN_DEPTH = 0;
async function runAiCommand(ctx, env, bot, command) {
  if (AI_RUN_DEPTH > 0) return null;
  const cmd = String(command || "").trim();
  if (!cmd.startsWith("/")) return null;
  const word = cmd.split(" ")[0].toLowerCase();
  if (!AI_RUN_ALLOW.has(word)) return null;
  if (word === "/ai" || word === "/aiham") return null;
  if (typeof INCOMING_HANDLER !== "function") return null;

  AI_RUN_DEPTH++;
  try {
    const base = ctx.message || ctx.msg || {};
    const patched = { ...base, text: cmd, caption: undefined };
    const sub = { ...ctx, message: patched, msg: patched };
    return await INCOMING_HANDLER(sub, env, bot);
  } finally {
    AI_RUN_DEPTH--;
  }
}

