function aiModelShort(id) {
  for (const [k, v] of Object.entries(AI_MODEL_KEYS)) if (v === id) return k;
  return id || "авто";
}
async function getAiPreferred(env, userId) {
  try {
    const s = await getUserSettings(env, userId);
    return s?.ai_model || null;
  } catch { return null; }
}
async function aiShort(env, system, user, maxLen = 3500, preferred = null) {
  let t = await runAi(env, [
    { role: "system", content: AI_IDENTITY + " " + system },
    { role: "user", content: String(user || "").slice(0, 2000) }
  ], preferred);
  t = t || "Пусто.";
  return t.length > maxLen ? t.slice(0, maxLen - 3) + "..." : t;
}
async function startQuiz(ctx, env, ownerId) {
  await ctx.reply(`🎲 <i>Придумываю вопрос...</i>`, { parse_mode: "HTML" });
  try {
    const t = await aiShort(env,
      "Придумай один интересный квиз-вопрос с однозначным коротким ответом. Формат СТРОГО две строки:\nВОПРОС: <текст вопроса>\nОТВЕТ: <короткий ответ>",
      "викторина", 600);
    const parts = t.split(/ОТВЕТ:/i);
    if (parts.length < 2) {
      await ctx.reply(`🎲 <b>Вопрос:</b>\n${escapeHtml(t)}`, { parse_mode: "HTML" });
      return;
    }
    const question = parts[0].replace(/ВОПРОС:/i, "").trim();
    const answer = parts[1].trim().replace(/\n/g, " ").slice(0, 200);
    await setUserState(env, ownerId, "await_quiz:::" + answer);
    await ctx.reply(`🎲 <b>Вопрос:</b>\n${escapeHtml(question)}\n\n<i>Отвечай следующим сообщением!</i>`, { parse_mode: "HTML" });
  } catch (e) {
    await ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
  }
}
const PIPED_INSTANCES = [
  "https://api.piped.private.coffee",
  "https://pipedapi.reallyaweso.me",
  "https://pipedapi.adminforge.de",
  "https://pipedapi.leptons.xyz",
  "https://pipedapi-libre.kavin.rocks",
  "https://pipedapi.kavin.rocks"
];

function youtubeIdFromUrl(value) {
  const s = String(value || "").trim();
  const patterns = [
    /[?&]v=([A-Za-z0-9_-]{11})/,
    /youtu\.be\/([A-Za-z0-9_-]{11})/,
    /\/embed\/([A-Za-z0-9_-]{11})/,
    /\/shorts\/([A-Za-z0-9_-]{11})/
  ];
  for (const re of patterns) {
    const m = s.match(re);
    if (m) return m[1];
  }
  return /^[A-Za-z0-9_-]{11}$/.test(s) ? s : null;
}

function normalizePipedTrack(item, filter) {
  if (!item || (item.type && item.type !== "stream" && item.type !== "STREAM")) return null;
  const id = youtubeIdFromUrl(item.url) || youtubeIdFromUrl(item.id);
  if (!id) return null;
  const isVideo = filter === "videos" || filter === "video";
  return {
    id,
    title: String(item.title || "Без названия").slice(0, 200),
    artist: String(item.uploaderName || item.uploader || "YouTube").slice(0, 120),
    duration: Math.max(0, parseInt(item.duration) || 0),
    thumbnail: String(item.thumbnail || `https://i.ytimg.com/vi/${id}/hqdefault.jpg`),
    link: `https://${isVideo ? "www.youtube.com" : "music.youtube.com"}/watch?v=${id}`
  };
}

async function pipedSearchPage(env, query, filter = "music_songs", limit = 5, preferredBase = "", nextpage = "") {
  const q = (query || "").trim().slice(0, 150);
  const cap = Math.max(1, Math.min(50, parseInt(limit) || 5));
  if (q.length < 2) return { tracks: [], base: null, nextpage: null };
  const bases = nextpage
    ? [preferredBase].filter(Boolean)
    : preferredBase
      ? [preferredBase, ...PIPED_INSTANCES.filter(x => x !== preferredBase)]
      : PIPED_INSTANCES;
  const searchBase = async (base) => {
    const endpoint = nextpage
      ? `${base}/nextpage/search?nextpage=${encodeURIComponent(nextpage)}&q=${encodeURIComponent(q)}&filter=${encodeURIComponent(filter)}`
      : `${base}/search?q=${encodeURIComponent(q)}&filter=${encodeURIComponent(filter)}`;
    const data = await fetchJsonTimeout(endpoint, 5000);
    const items = data?.items || data?.content || [];
    const tracks = [];
    for (const item of items) {
      const track = normalizePipedTrack(item, filter);
      if (track) tracks.push(track);
      if (tracks.length >= cap) break;
    }
    if (!tracks.length) throw new Error("empty");
    return {
      tracks,
      base,
      nextpage: data?.nextpage ? String(data.nextpage) : null
    };
  };
  if (!bases.length) return { tracks: [], base: null, nextpage: null };
  try {
    return await Promise.any(bases.map(searchBase));
  } catch {
    return { tracks: [], base: preferredBase || null, nextpage: null };
  }
}

async function pipedSearch(env, query, filter = "music_songs", limit = 5) {
  return pipedSearchPage(env, query, filter, limit);
}

function inlineSessionToken(sessionId, page) {
  return `i_${sessionId}_${page}`;
}

function inlineCursorFromOffset(offset) {
  const m = String(offset || "").match(/^i_([a-f0-9]{32})_(\d{1,9})$/);
  return m ? { sessionId: m[1], page: Math.max(1, parseInt(m[2]) || 1) } : null;
}

async function createInlineSession(env, userId, kind, query, payload) {
  const sessionId = crypto.randomUUID().replace(/-/g, "");
  const now = Math.floor(Date.now() / 1000);
  try {
    await env.DB.prepare(`
      INSERT INTO inline_sessions
      (session_id, user_id, kind, query, payload, page, expires_at)
      VALUES (?, ?, ?, ?, ?, 1, ?)
    `).bind(sessionId, Number(userId), kind, query, JSON.stringify(payload), now + 7200).run();
    return { sessionId, page: 1 };
  } catch {
    return null;
  }
}

async function loadInlineSession(env, userId, kind, query, offset) {
  const cursor = inlineCursorFromOffset(offset);
  if (!cursor) return null;
  try {
    const row = await env.DB.prepare(`
      SELECT session_id, page, payload, expires_at
      FROM inline_sessions
      WHERE session_id = ? AND user_id = ? AND kind = ? AND query = ? AND page = ?
    `).bind(cursor.sessionId, Number(userId), kind, query, cursor.page).first();
    if (!row) return null;
    if (Number(row.expires_at) <= Math.floor(Date.now() / 1000)) {
      await env.DB.prepare("DELETE FROM inline_sessions WHERE session_id = ?").bind(cursor.sessionId).run();
      return null;
    }
    const payload = JSON.parse(row.payload || "{}");
    if (!payload || typeof payload !== "object") return null;
    return { sessionId: cursor.sessionId, page: cursor.page, payload };
  } catch {
    return null;
  }
}

async function saveInlineSession(env, sessionId, expectedPage, payload) {
  try {
    const result = await env.DB.prepare(`
      UPDATE inline_sessions
      SET payload = ?, page = page + 1, expires_at = ?
      WHERE session_id = ? AND page = ?
    `).bind(JSON.stringify(payload), Math.floor(Date.now() / 1000) + 7200, sessionId, expectedPage).run();
    return Number(result?.meta?.changes) === 1;
  } catch {
    return false;
  }
}

async function deleteInlineSession(env, sessionId) {
  try {
    await env.DB.prepare("DELETE FROM inline_sessions WHERE session_id = ?").bind(sessionId).run();
  } catch {}
}

function freshInlineState(firstPage) {
  return {
    phase: "yt",
    ytBase: firstPage.base || null,
    ytNext: firstPage.nextpage || null,
    ytTracks: firstPage.tracks || [],
    ytDone: !(firstPage.tracks || []).length || !firstPage.nextpage,
    scTracks: [],
    scCid: null,
    scOffset: 0,
    scDone: false
  };
}

async function loadInlineMediaPage(env, userId, kind, query, offset, perPage = 10) {
  const cursor = inlineCursorFromOffset(offset);
  const session = cursor ? await loadInlineSession(env, userId, kind, query, offset) : null;
  if (cursor && !session) return { items: [], page: cursor.page, nextOffset: "" };
  const firstPage = session ? null : await pipedSearchPage(env, query, kind === "video" || kind === "shorts" ? "videos" : "music_songs", 20);
  const active = session || await createInlineSession(env, userId, kind, query, freshInlineState(firstPage));
  const state = session ? session.payload : freshInlineState(firstPage);
  const page = session ? session.page : 1;
  let items = [];

  for (let attempt = 0; attempt < 2 && !items.length; attempt++) {
    if (kind === "music" && state.phase === "sc") {
      if (!(state.scTracks || []).length && !state.scDone) {
        const sc = await searchSoundCloud(env, query, Number(state.scOffset) || 0, 20);
        state.scTracks = sc.tracks || [];
        state.scCid = sc.cid || state.scCid;
        state.scOffset = (Number(state.scOffset) || 0) + (sc.tracks || []).length;
        state.scDone = !(sc.tracks || []).length;
      }
      items = (state.scTracks || []).splice(0, perPage).map(track => ({ source: "sc", track, cid: state.scCid }));
    } else {
      if (!(state.ytTracks || []).length && !state.ytDone && state.ytNext) {
        const nextPage = await pipedSearchPage(env, query, kind === "video" || kind === "shorts" ? "videos" : "music_songs", 20, state.ytBase, state.ytNext);
        state.ytTracks = nextPage.tracks || [];
        state.ytBase = nextPage.base || state.ytBase;
        state.ytNext = nextPage.nextpage || null;
        state.ytDone = !(nextPage.tracks || []).length || !nextPage.nextpage;
      }
      items = (state.ytTracks || []).splice(0, perPage).map(track => ({ source: "yt", track }));
      if (kind === "music" && !items.length && state.ytDone) state.phase = "sc";
    }
  }

  let hasMore;
  if (kind === "music") {
    hasMore = state.phase === "sc"
      ? (state.scTracks || []).length > 0 || !state.scDone
      : (state.ytTracks || []).length > 0 || !state.ytDone || !state.scDone;
  } else {
    hasMore = (state.ytTracks || []).length > 0 || !state.ytDone;
  }

  const nextOffset = active && hasMore && items.length ? inlineSessionToken(active.sessionId, page + 1) : "";
  return {
    items,
    page,
    nextOffset,
    sessionId: active?.sessionId || null,
    expectedPage: page,
    state,
    hasMore
  };
}

async function loadInlineSoundCloudPage(env, userId, query, offset, perPage = 10) {
  const cursor = inlineCursorFromOffset(offset);
  const session = cursor ? await loadInlineSession(env, userId, "soundcloud", query, offset) : null;
  if (cursor && !session) return { items: [], page: cursor.page, nextOffset: "" };
  let state = session?.payload;
  let active = session;
  if (!state) {
    const first = await searchSoundCloud(env, query, 0, 20).catch(() => ({ tracks: [], cid: null }));
    state = {
      scTracks: first.tracks || [],
      scCid: first.cid || null,
      scOffset: (first.tracks || []).length,
      scDone: !(first.tracks || []).length
    };
    active = await createInlineSession(env, userId, "soundcloud", query, state);
  }
  if (!(state.scTracks || []).length && !state.scDone) {
    const next = await searchSoundCloud(env, query, Number(state.scOffset) || 0, 20).catch(() => ({ tracks: [], cid: null }));
    state.scTracks = next.tracks || [];
    state.scCid = next.cid || state.scCid;
    state.scOffset = (Number(state.scOffset) || 0) + (next.tracks || []).length;
    state.scDone = !(next.tracks || []).length;
  }
  const page = session ? session.page : 1;
  const items = (state.scTracks || []).splice(0, perPage).map(track => ({ source: "sc", track, cid: state.scCid }));
  const hasMore = (state.scTracks || []).length > 0 || !state.scDone;
  const nextOffset = active && hasMore && items.length ? inlineSessionToken(active.sessionId, page + 1) : "";
  return {
    items,
    page,
    nextOffset,
    sessionId: active?.sessionId || null,
    expectedPage: page,
    state,
    hasMore
  };
}

async function commitInlineMediaPage(env, page) {
  if (!page?.sessionId) return;
  if (page.hasMore && page.items?.length) {
    await saveInlineSession(env, page.sessionId, page.expectedPage, page.state);
  } else {
    await deleteInlineSession(env, page.sessionId);
  }
}

function bytesToBase64Url(bytes) {
  let binary = "";
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function base64UrlToBytes(value) {
  const normalized = String(value || "").replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized + "=".repeat((4 - normalized.length % 4) % 4);
  const binary = atob(padded);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}

function mediaSigningSecret(env) {
  return String(env.MEDIA_SIGNING_SECRET || env.WEBHOOK_SECRET || env.BOT_TOKEN || "");
}

async function mediaHmacKey(env) {
  const secret = mediaSigningSecret(env);
  if (!secret) return null;
  return crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"]
  );
}

async function mediaSignature(env, format, videoId, expires) {
  const key = await mediaHmacKey(env);
  if (!key) return "";
  const data = new TextEncoder().encode(`${format}:${videoId}:${expires}`);
  const signature = await crypto.subtle.sign("HMAC", key, data);
  return bytesToBase64Url(new Uint8Array(signature));
}

async function verifyMediaSignature(env, format, videoId, expires, signature) {
  const key = await mediaHmacKey(env);
  if (!key || !signature) return false;
  try {
    return await crypto.subtle.verify(
      "HMAC",
      key,
      base64UrlToBytes(signature),
      new TextEncoder().encode(`${format}:${videoId}:${expires}`)
    );
  } catch {
    return false;
  }
}

function supportedMediaSource(value) {
  try {
    const parsed = new URL(String(value));
    const host = parsed.hostname.toLowerCase();
    const youtube = host === "youtu.be" || host === "youtube.com" || host.endsWith(".youtube.com");
    const tiktok = host === "tiktok.com" || host.endsWith(".tiktok.com");
    if (!youtube && !tiktok) return null;
    return { url: parsed.toString(), type: youtube ? "youtube" : "tiktok" };
  } catch {
    return null;
  }
}

async function sourceMediaSignature(env, sourceUrl, format, expires) {
  const key = await mediaHmacKey(env);
  if (!key) return "";
  const data = new TextEncoder().encode(`source:${sourceUrl}:${format}:${expires}`);
  const signature = await crypto.subtle.sign("HMAC", key, data);
  return bytesToBase64Url(new Uint8Array(signature));
}

async function verifySourceMediaSignature(env, sourceUrl, format, expires, signature) {
  const key = await mediaHmacKey(env);
  if (!key || !signature) return false;
  try {
    return await crypto.subtle.verify(
      "HMAC",
      key,
      base64UrlToBytes(signature),
      new TextEncoder().encode(`source:${sourceUrl}:${format}:${expires}`)
    );
  } catch {
    return false;
  }
}

const MEDIA_BASE_URL = "https://cf-tg-spy.eldevcreatorru.workers.dev";

async function youtubeMediaUrl(env, videoId, format, ttlSeconds = 3600) {
  const id = youtubeIdFromUrl(videoId);
  if (!id || !["audio", "video"].includes(format)) return null;
  const expires = Math.floor(Date.now() / 1000) + Math.max(60, parseInt(ttlSeconds) || 3600);
  const signature = await mediaSignature(env, format, id, expires);
  if (!signature) return null;
  return `${MEDIA_BASE_URL}/media/youtube/${format}/${id}?expires=${expires}&signature=${encodeURIComponent(signature)}`;
}

async function externalMediaUrl(env, sourceUrl, format, ttlSeconds = 3600) {
  const source = supportedMediaSource(sourceUrl);
  if (!source || !["audio", "video"].includes(format)) return null;
  const expires = Math.floor(Date.now() / 1000) + Math.max(60, parseInt(ttlSeconds) || 3600);
  const signature = await sourceMediaSignature(env, source.url, format, expires);
  if (!signature) return null;
  return `${MEDIA_BASE_URL}/media/external/${format}?url=${encodeURIComponent(source.url)}&expires=${expires}&signature=${encodeURIComponent(signature)}`;
}

const COBALT_INSTANCES = [
  "https://rue-cobalt.xenon.zone",
  "https://api.cobalt.tools",
  "https://cobalt.api.timelessnesses.me",
  "https://cobalt-api.kwiatekmiki.com"
];

const MEDIA_MIME_BY_EXT = {
  mp3: "audio/mpeg",
  m4a: "audio/mp4",
  aac: "audio/aac",
  ogg: "audio/ogg",
  opus: "audio/ogg",
  weba: "audio/webm",
  webm: "video/webm",
  mp4: "video/mp4",
  m4v: "video/mp4",
  mov: "video/quicktime",
  flac: "audio/flac",
  wav: "audio/wav"
};

function mediaExtensionOf(filename, fallbackExt) {
  const fromName = String(filename || "").match(/\.([a-z0-9]{2,4})$/i);
  const ext = (fromName ? fromName[1] : fallbackExt || "mp3").toLowerCase();
  return MEDIA_MIME_BY_EXT[ext] ? ext : (fallbackExt || "mp3");
}

async function resolveCobaltMedia(env, sourceValue, format) {
  const sourceInfo = supportedMediaSource(sourceValue);
  if (!sourceInfo) return null;
  const source = sourceInfo.url;
  const requestedQuality = String(env.YT_VIDEO_QUALITY || "360");
  const videoQuality = ["144", "240", "360", "480", "720", "1080", "1440", "2160", "4320", "max"].includes(requestedQuality)
    ? requestedQuality
    : "360";
  const body = {
    url: source,
    downloadMode: format === "audio" ? "audio" : "auto",
    audioFormat: "mp3",
    audioBitrate: "128",
    filenameStyle: "basic",
    disableMetadata: false,
    localProcessing: "disabled"
  };
  if (format === "video" && sourceInfo.type === "youtube") {
    body.videoQuality = videoQuality;
    body.youtubeVideoCodec = "h264";
    body.youtubeVideoContainer = "mp4";
    body.youtubeHLS = false;
  }
  if (format === "video" && sourceInfo.type === "tiktok") body.tiktokFullAudio = true;
  const instances = [...new Set([env.COBALT_URL, ...COBALT_INSTANCES].filter(Boolean))];
  for (const instance of instances) {
    try {
      const headers = { "Accept": "application/json", "Content-Type": "application/json" };
      if (env.COBALT_API_KEY) headers.Authorization = `Api-Key ${env.COBALT_API_KEY}`;
      const data = await fetchJsonTimeout(String(instance).replace(/\/$/, ""), 12000, {
        method: "POST",
        headers,
        body: JSON.stringify(body)
      });
      if ((data?.status === "tunnel" || data?.status === "redirect") && data?.url) {
        const fallbackName = `${sourceInfo.type}.${format === "audio" ? "mp3" : "mp4"}`;
        return { url: String(data.url), filename: String(data.filename || fallbackName) };
      }
    } catch {}
  }
  return null;
}

async function pipedAudioFallback(env, videoId) {
  const id = youtubeIdFromUrl(videoId);
  if (!id) return null;
  const findStream = async (base) => {
    const data = await fetchJsonTimeout(`${base}/streams/${id}`, 5000);
    const streams = (data?.audioStreams || []).filter(s => s?.url);
    if (!streams.length) throw new Error("no audio stream");
    const score = (s) => {
      const mime = String(s.mimeType || "").toLowerCase();
      const codec = String(s.codec || "").toLowerCase();
      let value = Number(s.bitrate) || 0;
      if (mime.includes("mp4") || codec.includes("mp4a") || codec.includes("aac")) value += 60000;
      if (mime.includes("webm") || codec.includes("opus") || codec.includes("vorbis")) value += 20000;
      return value;
    };
    const best = streams.slice().sort((a, b) => score(b) - score(a))[0];
    const isMp4 = /mp4|aac/i.test(String(best.mimeType || "") + String(best.codec || ""));
    return {
      url: best.url,
      filename: `youtube-${id}.${isMp4 ? "m4a" : "webm"}`,
      duration: Math.round(Number(best.duration || data.duration || 0))
    };
  };
  try {
    return await Promise.any(PIPED_INSTANCES.map(findStream));
  } catch {
    return null;
  }
}

async function resolveYoutubeMedia(env, videoId, format) {
  const id = youtubeIdFromUrl(videoId);
  if (!id) return null;
  const direct = await resolveCobaltMedia(env, `https://www.youtube.com/watch?v=${id}`, format);
  if (direct) return direct;
  if (format === "audio") return await pipedAudioFallback(env, id);
  return await pipedVideoFallback(env, id);
}

async function pipedVideoFallback(env, videoId) {
  const id = youtubeIdFromUrl(videoId);
  if (!id) return null;
  const findStream = async (base) => {
    const data = await fetchJsonTimeout(`${base}/streams/${id}`, 4500);
    const streams = (data?.videoStreams || []).filter(s =>
      s?.url &&
      !s.videoOnly &&
      /video\/mp4/i.test(s.mimeType || "") &&
      /avc1|h264/i.test(s.codec || "")
    );
    streams.sort((a, b) => (Number(b.height) || 0) - (Number(a.height) || 0));
    const best = streams.find(s => (Number(s.height) || 0) <= 720) || streams[0];
    if (!best) throw new Error("no mp4");
    return { url: best.url, filename: `youtube-${id}.mp4` };
  };
  try {
    return await Promise.any(PIPED_INSTANCES.map(findStream));
  } catch {
    return null;
  }
}

async function proxyMediaResponse(request, env, format, media) {
  if (!media?.url) return new Response("Media unavailable", { status: 502 });
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);
    const upstreamHeaders = { "User-Agent": SEARCH_UA };
    const range = request.headers.get("Range");
    if (range) upstreamHeaders.Range = range;
    let upstream;
    try {
      upstream = await fetch(media.url, { headers: upstreamHeaders, signal: controller.signal });
    } finally {
      clearTimeout(timeout);
    }
    if (!upstream.ok || !upstream.body) return new Response("Upstream unavailable", { status: 502 });
    const reader = upstream.body.getReader();
    const first = await reader.read();
    if (first.done || !first.value || first.value.byteLength === 0) {
      try { await reader.cancel(); } catch {}
      return new Response("Upstream returned empty body", { status: 502 });
    }
    const replayed = new ReadableStream({
      start(controller) {
        controller.enqueue(first.value);
      },
      async pull(controller) {
        const { value, done } = await reader.read();
        if (done) { controller.close(); return; }
        if (value) controller.enqueue(value);
      },
      cancel(reason) {
        return reader.cancel(reason);
      }
    });
    const upstreamType = String(upstream.headers.get("content-type") || "").split(";")[0].trim().toLowerCase();
    const fallbackExt = format === "audio" ? "mp3" : "mp4";
    const ext = mediaExtensionOf(media.filename, upstreamType || fallbackExt);
    const safeBase = String(media.filename || `media.${ext}`).replace(/\.[A-Za-z0-9]{2,4}$/, "").replace(/[^A-Za-z0-9._ ()-]/g, "_").slice(0, 100);
    const filename = `${safeBase}.${ext}`;
    const exactLength = parseInt(upstream.headers.get("content-length") || "0") || 0;
    const contentRange = upstream.headers.get("content-range");
    const totalLength = parseInt(contentRange?.match(/\/(\d+)$/)?.[1] || "0") || 0;
    if ((exactLength && exactLength > 50 * 1024 * 1024) || (totalLength && totalLength > 50 * 1024 * 1024)) {
      try { await reader.cancel(); } catch {}
      return new Response("Media exceeds Telegram 50 MB limit", { status: 413 });
    }
    let body = replayed;
    if (!exactLength && !totalLength) {
      let sent = 0;
      const limiter = new TransformStream({
        transform(chunk, controller) {
          sent += chunk.byteLength;
          if (sent > 50 * 1024 * 1024) {
            controller.error(new Error("Telegram media limit exceeded"));
            return;
          }
          controller.enqueue(chunk);
        }
      });
      body = body.pipeThrough(limiter);
    }
    const headers = {
      "Content-Type": MEDIA_MIME_BY_EXT[ext] || upstreamType || (format === "audio" ? "audio/mpeg" : "video/mp4"),
      "Content-Disposition": `inline; filename="${filename}"`,
      "Cache-Control": "private, max-age=60",
      "X-Content-Type-Options": "nosniff",
      "Access-Control-Allow-Origin": "*",
      "Accept-Ranges": "bytes"
    };
    if (exactLength) headers["Content-Length"] = String(exactLength);
    if (contentRange) headers["Content-Range"] = contentRange;
    return new Response(body, { status: upstream.status === 206 ? 206 : 200, headers });
  } catch {
    return new Response("Upstream error", { status: 502 });
  }
}

async function streamYoutubeMedia(request, env, format, videoId, expires, signature) {
  if (request.method !== "GET") return new Response("Method not allowed", { status: 405 });
  const exp = parseInt(expires) || 0;
  if (exp <= Math.floor(Date.now() / 1000)) return new Response("Link expired", { status: 410 });
  if (!(await verifyMediaSignature(env, format, videoId, exp, signature))) return new Response("Forbidden", { status: 403 });
  let media = await resolveYoutubeMedia(env, videoId, format);
  if (!media && format === "video") media = await pipedVideoFallback(env, videoId);
  if (!media) return new Response("Media unavailable", { status: 502 });
  return proxyMediaResponse(request, env, format, media);
}

async function streamExternalMedia(request, env, format, sourceUrl, expires, signature) {
  if (request.method !== "GET") return new Response("Method not allowed", { status: 405 });
  const exp = parseInt(expires) || 0;
  if (exp <= Math.floor(Date.now() / 1000)) return new Response("Link expired", { status: 410 });
  const source = supportedMediaSource(sourceUrl);
  if (!source || !(await verifySourceMediaSignature(env, source.url, format, exp, signature))) return new Response("Forbidden", { status: 403 });
  let media = await resolveCobaltMedia(env, source.url, format);
  if (!media) {
    const pipedHint = String(source.url).match(/v=([A-Za-z0-9_-]{6,})/)?.[1];
    if (pipedHint) media = format === "audio" ? await pipedAudioFallback(env, pipedHint) : await pipedVideoFallback(env, pipedHint);
  }
  return proxyMediaResponse(request, env, format, media);
}

const WORKER_UPLOAD_LIMIT = 49 * 1024 * 1024;

function safeUploadName(name, fallbackExt) {
  const ext = mediaExtensionOf(name, fallbackExt);
  const base = String(name || "media").replace(/\.[A-Za-z0-9]{2,4}$/, "").replace(/[^A-Za-z0-9._ ()-]/g, "_").trim().slice(0, 80) || "media";
  return `${base}.${ext}`;
}

async function downloadMediaPayload(url, limitBytes = WORKER_UPLOAD_LIMIT) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 30000);
    let res;
    try {
      res = await fetch(url, { headers: { "User-Agent": SEARCH_UA }, signal: controller.signal });
    } finally {
      clearTimeout(timer);
    }
    if (!res.ok) {
      await discardBody(res);
      return null;
    }
    const declared = parseInt(res.headers.get("content-length") || "0") || 0;
    if (declared && declared > limitBytes) {
      await discardBody(res);
      return null;
    }
    const buffer = await res.arrayBuffer();
    if (!buffer || buffer.byteLength === 0 || buffer.byteLength > limitBytes) return null;
    const type = String(res.headers.get("content-type") || "").split(";")[0].trim().toLowerCase();
    return { bytes: new Uint8Array(buffer), contentType: type, size: buffer.byteLength };
  } catch {
    return null;
  }
}

async function sendAudioRobust(ctx, env, mediaUrl, resolveHint, opts = {}) {
  if (mediaUrl) {
    try {
      return await ctx.replyWithAudio(mediaUrl, opts);
    } catch {}
  }
  const media = resolveHint ? await resolveHint() : null;
  if (media && media.url && media.url !== mediaUrl) {
    try {
      return await ctx.replyWithAudio(media.url, opts);
    } catch {}
  }
  if (media?.url) {
    const payload = await downloadMediaPayload(media.url);
    if (payload) {
      const ext = mediaExtensionOf(media.filename, "mp3");
      try {
        return await ctx.replyWithAudio(new InputFile(payload.bytes, safeUploadName(media.filename, ext)), opts);
      } catch {}
    }
  }
  return null;
}

async function sendVideoRobust(ctx, env, mediaUrl, resolveHint, opts = {}) {
  if (mediaUrl) {
    try {
      return await ctx.replyWithVideo(mediaUrl, opts);
    } catch {}
  }
  const media = resolveHint ? await resolveHint() : null;
  if (media?.url) {
    const payload = await downloadMediaPayload(media.url);
    if (payload) {
      const ext = mediaExtensionOf(media.filename, "mp4");
      try {
        return await ctx.replyWithVideo(new InputFile(payload.bytes, safeUploadName(media.filename, ext)), opts);
      } catch {}
    }
  }
  return null;
}

