async function radioBrowserStations(query, limit = 6) {
  const q = String(query || "").trim();
  const cap = Math.max(1, Math.min(30, limit));
  const path = q
    ? `/json/stations/search?limit=${cap}&hidebroken=true&order=clickcount&reverse=true&name=${encodeURIComponent(q)}`
    : `/json/stations/search?limit=${cap}&hidebroken=true&order=clickcount&reverse=true`;
  for (const base of RADIO_BROWSER_MIRRORS) {
    const data = await fetchJsonTimeout(`${base}${path}`, 9000);
    const items = Array.isArray(data) ? data : [];
    if (!items.length) continue;
    return items
      .filter(s => s?.name && (s.url_resolved || s.url))
      .map(s => ({
        source: "radio",
        title: String(s.name),
        artist: String(s.country || "Радио"),
        album: String(s.tags || ""),
        duration: 0,
        preview: String(s.url_resolved || s.url),
        link: String(s.homepage || s.url_resolved || s.url),
        cover: s.favicon || "",
        codec: String(s.codec || ""),
        bitrate: Number(s.bitrate) || 0
      }));
  }
  return [];
}

function normalizedTitle(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, " ")
    .replace(/\b(feat|ft|with|official|video|audio|lyrics|remaster(ed)?|explicit|hd|hq|4k|1080p|mp3)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function musicSimilarity(a, b) {
  const x = normalizedTitle(a).split(" ").filter(Boolean);
  const y = normalizedTitle(b).split(" ").filter(Boolean);
  if (!x.length || !y.length) return 0;
  const ys = new Set(y);
  let hit = 0;
  for (const w of x) if (ys.has(w)) hit++;
  return hit / Math.max(x.length, y.length);
}

function pickBestPreview(tracks, source) {
  const playable = tracks.filter(t => t.source === source && t.preview);
  if (!playable.length) return null;
  const query = normalizedTitle(tracks[0]?.title || "");
  const scored = playable.map(t => ({ t, score: musicSimilarity(`${t.artist} ${t.title}`, `${tracks[0]?.artist || ""} ${query}`) }));
  scored.sort((a, b) => b.score - a.score);
  return scored[0].t;
}

async function collectMusicTracks(env, query, sources) {
  const q = String(query || "").trim().slice(0, 150);
  const wanted = new Set(Array.isArray(sources) && sources.length ? sources : ["youtube", "soundcloud", "deezer", "itunes"]);
  const [yt, sc, dz, it] = await Promise.all([
    wanted.has("youtube") ? pipedSearch(env, q, "music_songs", 6).catch(() => ({ tracks: [], base: null })) : Promise.resolve({ tracks: [] }),
    wanted.has("soundcloud") ? searchSoundCloud(env, q, 0, 6).catch(() => ({ tracks: [], cid: null })) : Promise.resolve({ tracks: [] }),
    wanted.has("deezer") ? deezerSearch(q, 6) : Promise.resolve([]),
    wanted.has("itunes") ? itunesSearch(q, 6) : Promise.resolve([])
  ]);
  const list = [];
  for (const t of yt.tracks || []) list.push({ source: "youtube", title: t.title, artist: t.artist, duration: t.duration || 0, preview: null, link: t.link, ytId: t.id });
  for (const t of sc.tracks || []) list.push({ source: "soundcloud", title: t.title, artist: t.artist, duration: t.duration || 0, preview: null, link: t.link, scTrack: t, scCid: sc.cid });
  for (const t of dz) list.push(t);
  for (const t of it) list.push(t);
  return { list, yt, sc };
}

function musicListText(query, list, opts = {}) {
  const perSource = opts.perSource || 4;
  let out = `🎧 <b>${escapeHtml(opts.title || `По запросу «${query}»`)}</b>\n`;
  const grouped = {};
  for (const t of list) {
    if (!grouped[t.source]) grouped[t.source] = [];
    if (grouped[t.source].length < perSource) grouped[t.source].push(t);
  }
  const order = MUSIC_SOURCE_ORDER.filter(s => grouped[s]?.length);
  for (const s of order) {
    out += `\n${musicSourceLine(s, `${grouped[s].length} треков`)}\n`;
    grouped[s].forEach((t, i) => {
      const dur = t.duration ? ` <i>(${fmtDur(t.duration)})</i>` : "";
      const link = t.link ? ` (<a href="${escapeHtml(t.link)}">открыть</a>)` : "";
      out += `${i + 1}. <b>${escapeHtml(t.title)}</b> — ${escapeHtml(t.artist)}${dur}${link}\n`;
    });
  }
  if (!order.length) out += `\n😔 Ничего не нашлось.`;
  return out;
}

function musicAudioCaption(track, note) {
  const label = musicSourceLabel(track.source);
  const icon = musicSourceIcon(track.source);
  return withCredit(`${icon} <b>${escapeHtml(track.title)}</b> — ${escapeHtml(track.artist)}\n<i>🎼 Источник: ${escapeHtml(label)}${note ? ` • ${escapeHtml(note)}` : ""}</i>`);
}

async function sendTrackAudio(ctx, env, track, note) {
  if (!track?.preview) return false;
  const opts = {
    title: String(track.title || "Трек").slice(0, 100),
    performer: String(track.artist || musicSourceLabel(track.source)).slice(0, 100),
    caption: musicAudioCaption(track, note)
  };
  const sent = await sendAudioRobust(ctx, env, track.preview, null, opts);
  if (sent) return true;
  if (track.source === "soundcloud" && track.scTrack) {
    const stream = await resolveScStream(env, track.scTrack, track.scCid).catch(() => null);
    if (stream) return Boolean(await sendAudioRobust(ctx, env, stream, null, opts));
  }
  return false;
}

async function doMusicDeepSearch(ctx, env, query) {
  const parsed = parseMusicQuery(query);
  const q = parsed.query.slice(0, 150);
  const source = parsed.source;
  if (source === "apple") return doTrack(ctx, q);
  if (source === "spotify") return doSpotify(ctx, env, q);
  if (source === "yandex") return doYandexMusic(ctx, env, q);
  if (source === "radio") return doWebRadio(ctx, env, q);
  if (q.length < 2) {
    return ctx.reply(withCredit("❌ Формат: <code>/music название</code>, <code>/music youtube название</code>, <code>/music soundcloud название</code>, <code>/music deezer</code>, <code>/music apple</code>, <code>/music spotify</code>, <code>/music yandex</code>"), { parse_mode: "HTML" });
  }
  const wantYoutube = source === "youtube" || source === "all";
  const wantSc = source === "soundcloud" || source === "all";
  const wantDeezer = source === "deezer" || source === "all";
  const wantItunes = source === "itunes" || source === "apple" || source === "all";
  const label = source === "all" ? "YouTube Music, SoundCloud, Deezer и Apple Music" : musicSourceLabel(source === "apple" ? "itunes" : source === "youtube" ? "youtube" : source);
  await ctx.reply(`🎧 <i>Ищу «${escapeHtml(q)}» в ${escapeHtml(label)}...</i>`, { parse_mode: "HTML" });

  const { list } = await collectMusicTracks(env, q, [
    wantYoutube ? "youtube" : null,
    wantSc ? "soundcloud" : null,
    wantDeezer ? "deezer" : null,
    wantItunes ? "itunes" : null
  ].filter(Boolean));

  if (!list.length) {
    return ctx.reply(withCredit(`🎧 По запросу «${escapeHtml(q)}» ничего не нашлось в ${escapeHtml(label)}.`), { parse_mode: "HTML" });
  }

  const audioCandidates = [];
  const anchorTrack = list[0] || null;
  const scBest = pickBestPreview(list, "soundcloud") || list.find(t => t.source === "soundcloud") || null;
  const dzBest = pickBestPreview(list, "deezer") || list.find(t => t.source === "deezer") || null;
  const itBest = pickBestPreview(list, "itunes") || list.find(t => t.source === "itunes") || null;
  if (scBest) audioCandidates.push({ track: scBest, note: `совпадение ${Math.round(musicSimilarity(`${scBest.artist} ${scBest.title}`, `${anchorTrack?.artist || ""} ${anchorTrack?.title || ""}`) * 100)}%` });
  if (dzBest) audioCandidates.push({ track: dzBest, note: "превью 30 сек" });
  if (itBest) audioCandidates.push({ track: itBest, note: "превью 30 сек" });

  let sentAudio = false;
  for (const cand of audioCandidates) {
    if (sentAudio) break;
    sentAudio = await sendTrackAudio(ctx, env, cand.track, cand.note);
  }

  let out = musicListText(q, list, { title: `Результаты по «${q}»` });
  if (!sentAudio) {
    out += `\n<i>⚠️ Аудио не подтянулось — открывай по ссылкам выше.</i>\n`;
  } else {
    out += `\n<i>🔊 Выше отправил лучший доступный трек. Полную версию ищи в Deezer / Apple Music / SoundCloud.</i>\n`;
  }
  out += `\n<b>Ещё источники:</b>\n<a href="${escapeHtml(spotifySearchUrl(q))}">🟢 Spotify</a> • <a href="${escapeHtml(yandexSearchUrl(q))}">🔴 Яндекс Музыка</a> • <a href="https://www.youtube.com/results?search_query=${encodeURIComponent(q)}">▶️ YouTube</a>\n`;
  out += `\n<i>Только один источник: <code>/music deezer запрос</code> • <code>/music soundcloud запрос</code> • <code>/music apple запрос</code> • <code>/music spotify запрос</code> • <code>/music yandex запрос</code></i>`;
  out = withCredit(out);
  try {
    await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  } catch {
    await ctx.reply(out, { parse_mode: "HTML" });
  }
}

async function doSoundCloud(ctx, env, argStr) {
  const q = String(argStr || "").trim().slice(0, 150);
  if (q.length < 2) return ctx.reply(withCredit("❌ Формат: <code>/soundcloud название трека</code>"), { parse_mode: "HTML" });
  await ctx.reply(`🟠 <i>Ищу в SoundCloud: «${escapeHtml(q)}»...</i>`, { parse_mode: "HTML" });
  const sc = await searchSoundCloud(env, q, 0, 8).catch(() => ({ tracks: [], cid: null }));
  if (!sc.tracks.length) return ctx.reply(withCredit(`🟠 По запросу «${escapeHtml(q)}» в SoundCloud ничего не нашлось.`), { parse_mode: "HTML" });
  const top = sc.tracks[0];
  const stream = await resolveScStream(env, top, sc.cid).catch(() => null);
  let sent = false;
  if (stream) {
    sent = Boolean(await sendAudioRobust(ctx, env, stream, null, {
      title: top.title.slice(0, 100),
      performer: top.artist.slice(0, 100),
      caption: withCredit(`🎧 <b>${escapeHtml(top.title)}</b> — ${escapeHtml(top.artist)}\n<i>🟠 Источник: SoundCloud</i>`),
      parse_mode: "HTML"
    }));
  }
  let out = `🟠 <b>SoundCloud: «${escapeHtml(q)}»</b>\n───────────────────────\n`;
  sc.tracks.forEach((t, i) => {
    const dur = t.duration ? ` <i>(${fmtDur(t.duration)})</i>` : "";
    out += `${i + 1}. <b>${escapeHtml(t.title)}</b> — ${escapeHtml(t.artist)}${dur}${t.link ? ` (<a href="${t.link}">слушать</a>)` : ""}\n`;
  });
  if (!sent) out += `\n<i>⚠️ Аудио не подтянулось — открывай по ссылкам.</i>\n`;
  out += `\n<i>Ещё: <code>/music ${escapeHtml(q)}</code> — поиск по всем источникам сразу.</i>`;
  return ctx.reply(withCredit(out), { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
}
