function isProgressiveAudio(url) {
  const value = String(url || "").toLowerCase();
  if (!/^https?:\/\//.test(value)) return false;
  if (/\.m3u8(\?|$)|\/hls\b|manifest\.mpd(\?|$)/.test(value)) return false;
  return /\.(mp3|aac|ogg|oga|opus|flac|wav|mp4)(\?|$)/.test(value) || /\/listen\b|\/stream\b|icecast/.test(value);
}
async function doWebRadio(ctx, env, argStr) {
  const q = String(argStr || "").trim().slice(0, 100);
  await ctx.reply(`📻 <i>Ищу радиостанции по «${escapeHtml(q || "популярное")}»...</i>`, { parse_mode: "HTML" });
  const stations = await radioBrowserStations(q, 8);
  if (!stations.length) return ctx.reply(withCredit("📻 Станции не нашлись. Попробуй другое слово."), { parse_mode: "HTML" });
  const playable = stations.filter(s => isProgressiveAudio(s.preview));
  const first = playable[0] || null;
  let sent = false;
  if (first?.preview) {
    sent = Boolean(await sendAudioRobust(ctx, env, first.preview, null, {
      title: String(first.title).slice(0, 100),
      performer: String(first.artist).slice(0, 100),
      caption: withCredit(`📻 <b>${escapeHtml(first.title)}</b>\n<i>🎼 Источник: Радио (Radio Browser) • прямой эфир</i>`),
      parse_mode: "HTML"
    }));
  }
  let out = `📻 <b>Радио по «${escapeHtml(q || "популярное")}»:</b>\n───────────────────────\n`;
  stations.forEach((s, i) => {
    const br = s.bitrate ? ` <i>${s.bitrate} kbps</i>` : "";
    out += `${i + 1}. <b>${escapeHtml(String(s.title).slice(0, 60))}</b> — ${escapeHtml(s.artist)}${br} (<a href="${escapeHtml(s.link)}">сайт</a>)\n`;
  });
  out += `\n<i>Включить станцию: <code>/webradio ${escapeHtml(String(stations[0].title).split(" ")[0])}</code></i>`;
  if (!sent) out += `\n<i>⚠️ Прямой поток не нашёлся (часть станций только HLS) — открывай станцию по ссылке.</i>`;
  out = withCredit(out);
  try { await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } }); } catch { await ctx.reply(out, { parse_mode: "HTML" }); }
}

async function doMusicSearch(ctx, env, argStr) {
  return doMusicDeepSearch(ctx, env, argStr);
}

async function buildInlineSourceResults(source, query, offset) {
  const off = Math.max(0, parseInt(offset) || 0);
  const per = 5;
  if (source === "spotify") {
    const found = await searxSearch(`site:open.spotify.com/track ${query}`, 1, 10, stableSearchBase(`site:open.spotify.com/track ${query}`)).catch(() => []);
    const slice = found.slice(off, off + per);
    const results = slice.map((r, i) => ({
      type: "article",
      id: `sp_${off + i}`,
      title: `🟢 ${String(r.title || "Spotify").slice(0, 74)}`,
      description: `${off + i + 1}/${found.length} • Spotify`,
      input_message_content: { message_text: withCredit(`🟢 <a href="${escapeHtml(r.url)}">${escapeHtml(String(r.title).slice(0, 120))}</a>${r.snippet ? `\n<i>${escapeHtml(r.snippet.slice(0, 160))}</i>` : ""}\n<i>🎼 Источник: Spotify</i>`), parse_mode: "HTML" }
    }));
    if (!results.length && off === 0) results.push({ type: "article", id: "sp_none", title: "🟢 Spotify: не найдено", description: "Открыть поиск", input_message_content: { message_text: withCredit(`🟢 <a href="${escapeHtml(spotifySearchUrl(query))}">Открыть поиск в Spotify</a>`), parse_mode: "HTML" } });
    return { results, nextOffset: off + per < found.length ? String(off + per) : "" };
  }
  if (source === "yandex") {
    const found = await searxSearch(`site:music.yandex.ru/track ${query}`, 1, 10, stableSearchBase(`site:music.yandex.ru/track ${query}`)).catch(() => []);
    const slice = found.slice(off, off + per);
    const results = slice.map((r, i) => ({
      type: "article",
      id: `ym_${off + i}`,
      title: `🔴 ${String(r.title || "Яндекс Музыка").slice(0, 74)}`,
      description: `${off + i + 1}/${found.length} • Яндекс Музыка`,
      input_message_content: { message_text: withCredit(`🔴 <a href="${escapeHtml(r.url)}">${escapeHtml(String(r.title).slice(0, 120))}</a>${r.snippet ? `\n<i>${escapeHtml(r.snippet.slice(0, 160))}</i>` : ""}\n<i>🎼 Источник: Яндекс Музыка</i>`), parse_mode: "HTML" }
    }));
    if (!results.length && off === 0) results.push({ type: "article", id: "ym_none", title: "🔴 Яндекс Музыка: не найдено", description: "Открыть поиск", input_message_content: { message_text: withCredit(`🔴 <a href="${escapeHtml(yandexSearchUrl(query))}">Открыть поиск в Яндекс Музыке</a>`), parse_mode: "HTML" } });
    return { results, nextOffset: off + per < found.length ? String(off + per) : "" };
  }
  if (source === "radio") {
    const stations = await radioBrowserStations(query, 15);
    const playable = stations.filter(st => isProgressiveAudio(st.preview));
    const slice = playable.slice(off, off + per);
    const results = slice.map((st, i) => ({
      type: "audio",
      id: `rb_${off + i}`,
      audio_url: st.preview,
      title: `📻 ${String(st.title).slice(0, 70)}`,
      performer: String(st.artist || "Радио").slice(0, 60),
      caption: withCredit(`📻 <b>${escapeHtml(String(st.title).slice(0, 100))}</b> — ${escapeHtml(st.artist)}\n<i>🎼 Источник: Радио (Radio Browser) • прямой эфир</i>`),
      parse_mode: "HTML",
      thumbnail_url: st.cover || undefined
    }));
    const others = playable.length ? playable : stations;
    others.slice(0, 5).forEach((st, i) => {
      if (st.preview && isProgressiveAudio(st.preview)) return;
      results.push({ type: "article", id: `rbl_${i}`, title: `📻 ${String(st.title).slice(0, 70)}`, description: `${st.bitrate ? st.bitrate + " kbps" : "Радио"} • ссылка`, input_message_content: { message_text: withCredit(`📻 <a href="${escapeHtml(st.link)}">${escapeHtml(String(st.title).slice(0, 120))}</a>\n<i>🎼 Источник: Радио</i>`), parse_mode: "HTML" } });
    });
    if (!results.length && off === 0) results.push({ type: "article", id: "rb_none", title: "📻 Радио не найдено", description: "Попробуй другое слово", input_message_content: { message_text: withCredit("📻 Станции не нашлись. Попробуй другое слово."), parse_mode: "HTML" } });
    return { results, nextOffset: off + per < playable.length ? String(off + per) : "" };
  }
  const [dz, it] = await Promise.all([
    source === "deezer" ? deezerSearch(query, 12) : Promise.resolve([]),
    source === "itunes" ? itunesSearch(query, 12) : Promise.resolve([])
  ]);
  const merged = [
    ...dz.map(t => ({ ...t, note: "превью 30 сек" })),
    ...it.map(t => ({ ...t, note: "превью 30 сек" }))
  ];
  const slice = merged.slice(off, off + per);
  const results = slice.map((t, i) => ({
    type: "audio",
    id: `${t.source}_${off + i}`,
    audio_url: t.preview,
    title: `${musicSourceIcon(t.source)} ${off + 1 + i}. ${String(t.title).slice(0, 70)}`,
    performer: String(t.artist).slice(0, 60),
    caption: musicAudioCaption(t, t.note),
    parse_mode: "HTML",
    thumbnail_url: t.cover || undefined
  }));
  if (!results.length && off === 0) {
    results.push({ type: "article", id: "dz_none", title: "🎧 Ничего не нашлось", description: "Попробуй другой запрос", input_message_content: { message_text: withCredit(`🎧 Ничего не нашлось в ${escapeHtml(musicSourceLabel(source))}.`), parse_mode: "HTML" } });
  }
  return { results, nextOffset: off + per < merged.length ? String(off + per) : "" };
}
