function textFuncListText() {
  let out = `✍️ <b>ТЕКСТОВЫЕ ФУНКЦИИ</b>\n───────────────────────\n`;
  for (const f of TEXT_FUNCS) out += `${f.icon} <code>${f.cmd}</code> — ${escapeHtml(f.desc)}\n`;
  out += `\n<i>Каждая применяется к тексту после команды: <code>/bold Привет</code></i>`;
  return out;
}

function getTextFuncKeyboard() {
  const rows = [];
  for (let i = 0; i < TEXT_FUNCS.length; i += 2) {
    const row = [{ text: `${TEXT_FUNCS[i].icon} ${TEXT_FUNCS[i].name}`, callback_data: `tf:${TEXT_FUNCS[i].cmd.slice(1)}` }];
    if (TEXT_FUNCS[i + 1]) row.push({ text: `${TEXT_FUNCS[i + 1].icon} ${TEXT_FUNCS[i + 1].name}`, callback_data: `tf:${TEXT_FUNCS[i + 1].cmd.slice(1)}` });
    rows.push(row);
  }
  rows.push([{ text: "📋 Список функций", callback_data: "tf:list" }]);
  return { inline_keyboard: rows };
}

function applyTextFunc(rawName, text) {
  const name = String(rawName || "").trim().toLowerCase().replace(/^\//, "");
  const t = String(text || "").trim();
  const NO_TEXT = new Set(["dice", "flip", "ruyi"]);
  if (!t && !NO_TEXT.has(name)) return null;
  switch (name) {
    case "bold": return `<b>${escapeHtml(t)}</b>`;
    case "italic": return `<i>${escapeHtml(t)}</i>`;
    case "mono": return `<code>${escapeHtml(t)}</code>`;
    case "under": return `<u>${escapeHtml(t)}</u>`;
    case "leet": return t.replace(/a/gi, "4").replace(/e/gi, "3").replace(/i/gi, "1").replace(/o/gi, "0").replace(/s/gi, "5").replace(/t/gi, "7").replace(/b/gi, "8").replace(/g/gi, "9");
    case "kawaii": return `🌸 ${t} 🌸\n(◕‿◕) ✨`;
    case "tsundere": return `Х-хм... ${t}\n<i>(я не делаю это потому что ты мне нравишься!)</i>`;
    case "yandere": return `💕 ${t} 💕\n<i>(я буду любить тебя вечно...)</i>`;
    case "spoiler": return `||${t}||`;
    case "burn": return `🔥 ${t} 🔥\n<i>(это сообщение самоуничтожится...)</i>`;
    case "dice": return `🎲 <b>${1 + Math.floor(Math.random() * 6)}</b>`;
    case "flip": return Math.random() < 0.5 ? "🦅 <b>Орёл!</b>" : "🪙 <b>Решка!</b>";
    case "taost": return `☯️ <b>Тао говорит:</b> ${t}\n<i>(путь — это не пункт назначения)</i>`;
    case "ruyi": return Math.random() < 0.5 ? "🔫 <b>Пусто. Ты жив!</b>" : "💀 <b>БАХ. Не повезло.</b>";
    default: return null;
  }
}

async function doTextFunc(ctx, env, argStr, cmdName) {
  const forced = String(cmdName || "").replace(/^\//, "").toLowerCase();
  if (forced) {
    const text = String(argStr || "").trim();
    if (!text) {
      await setUserState(env, Number(ctx.from?.id), "await_textfunc:" + forced).catch(() => {});
      return ctx.reply(withCredit(`✍️ <b>Функция «${escapeHtml(forced)}».</b>\n\nПришли текст следующим сообщением.\n<i>Отмена: /cancel</i>`), { parse_mode: "HTML" });
    }
    const outDirect = applyTextFunc(forced, text);
    if (!outDirect) {
      return ctx.reply(withCredit(`❌ Не знаю функцию <code>${escapeHtml(forced)}</code>.\n\n${textFuncListText()}`), { parse_mode: "HTML", link_preview_options: { is_disabled: true }, reply_markup: getTextFuncKeyboard() });
    }
    return ctx.reply(withCredit(outDirect), { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  }
  const raw = String(argText(argStr)).trim();
  if (!raw) {
    return ctx.reply(withCredit(textFuncListText()), { parse_mode: "HTML", link_preview_options: { is_disabled: true }, reply_markup: getTextFuncKeyboard() });
  }
  const [name, ...rest] = raw.split(" ");
  const text = rest.join(" ");
  const out = applyTextFunc(name.toLowerCase().replace(/^\//, ""), text);
  if (!out) {
    return ctx.reply(withCredit(`❌ Не знаю функцию <code>${escapeHtml(name)}</code>.\n\n${textFuncListText()}`), { parse_mode: "HTML", link_preview_options: { is_disabled: true }, reply_markup: getTextFuncKeyboard() });
  }
  return ctx.reply(withCredit(out), { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
}

function argText(argStr) {
  return String(argStr || "").replace(/^\/\S+\s*/, "");
}

