function secDaysAgo(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString().slice(0, 10);
}

function secToday() {
  return new Date().toISOString().slice(0, 10);
}

function secWeekday(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  return ["вс", "пн", "вт", "ср", "чт", "пт", "сб"][d.getDay()];
}

async function secGetNotes(env, userId, limit = 50) {
  return env.DB.prepare("SELECT * FROM sec_notes WHERE user_id = ? ORDER BY created_at DESC LIMIT ?").bind(userId, limit).all().catch(() => ({ results: [] }));
}

async function secGetJournal(env, userId, days = 7) {
  return env.DB.prepare("SELECT * FROM sec_journal WHERE user_id = ? AND date >= ? ORDER BY date DESC").bind(userId, secDaysAgo(days)).all().catch(() => ({ results: [] }));
}

async function secGetHabits(env, userId) {
  return env.DB.prepare("SELECT * FROM sec_habits WHERE user_id = ? ORDER BY created_at ASC").bind(userId).all().catch(() => ({ results: [] }));
}

async function secGetGoals(env, userId) {
  return env.DB.prepare("SELECT * FROM sec_goals WHERE user_id = ? ORDER BY created_at DESC").bind(userId).all().catch(() => ({ results: [] }));
}

async function secGetHabitLogs(env, userId, days = 7) {
  return env.DB.prepare("SELECT * FROM sec_habit_logs WHERE user_id = ? AND date >= ? ORDER BY date DESC").bind(userId, secDaysAgo(days)).all().catch(() => ({ results: [] }));
}

async function secBuildContext(env, userId) {
  const [notes, journal, habits, goals] = await Promise.all([
    secGetNotes(env, userId, 30),
    secGetJournal(env, userId, 30),
    secGetHabits(env, userId),
    secGetGoals(env, userId)
  ]);
  return [
    notes?.results?.length ? `Заметки:\n${notes.results.map((n) => `- ${n.title}: ${n.content}`).join("\n")}` : "",
    journal?.results?.length ? `Дневник:\n${journal.results.map((j) => `- ${j.date} (настроение ${j.mood}/5): ${j.content}`).join("\n")}` : "",
    habits?.results?.length ? `Привычки:\n${habits.results.map((h) => `- ${h.icon || ""} ${h.name}`).join("\n")}` : "",
    goals?.results?.length ? `Цели:\n${goals.results.map((g) => `- ${g.title} (${g.status}${g.deadline ? ", до " + g.deadline : ""})`).join("\n")}` : ""
  ].filter(Boolean).join("\n\n");
}

async function secAskAi(env, userId, question) {
  const context = await secBuildContext(env, userId);
  return aiAskWithSearch(env, question, context || "у пользователя пока нет сохранённых данных");
}

async function secWeeklyAi(env, userId) {
  const [journal, habits, logs, goals, notes] = await Promise.all([
    secGetJournal(env, userId, 7),
    secGetHabits(env, userId),
    secGetHabitLogs(env, userId, 7),
    secGetGoals(env, userId),
    secGetNotes(env, userId, 50)
  ]);
  const context = [
    `Записи дневника за неделю:\n${(journal?.results || []).map((j) => `- ${j.date}, настроение ${j.mood}/5: ${j.content}`).join("\n") || "- нет"}`,
    `Привычки:\n${(habits?.results || []).map((h) => `- ${h.name}`).join("\n") || "- нет"}`,
    `Отметки привычек по дням:\n${(logs?.results || []).map((l) => `- ${l.date}: привычка #${l.habit_id} ${l.done ? "выполнена" : "не выполнена"}`).join("\n") || "- нет"}`,
    `Цели:\n${(goals?.results || []).map((g) => `- ${g.title} (${g.status})`).join("\n") || "- нет"}`,
    `Заметки:\n${(notes?.results || []).slice(0, 20).map((n) => `- ${n.title}: ${n.content}`).join("\n") || "- нет"}`
  ].join("\n\n");
  return aiAskWithSearch(
    env,
    "Составь итог недели по моим данным: как настроение, что получилось, что провалилось, главный вывод и 3 совета на следующую неделю. Без воды, по-человечески.",
    context
  );
}

