async function cmdContactAi(ctx, env, ownerId, query, kind, extra = "") {
  const h = await getIncomingHistory(env, ownerId, query);
  if (h.error) {
    await ctx.reply(h.error, { parse_mode: "HTML" });
    return;
  }
  const cfg = CONTACT_AI[kind];
  await ctx.reply(cfg.think, { parse_mode: "HTML" });
  try {
    const t = await aiShort(env, cfg.system, (extra ? "Контекст: " + extra + "\n" : "") + h.log, 2500);
    await ctx.reply(`${cfg.title}: ${escapeHtml(h.target.full_name)}</b>\n───────────────────────\n${withCreditEscaped(t)}`, { parse_mode: "HTML" });
  } catch (e) {
    await ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
  }
}
const PHOTO_BYTES = {};
const PHOTO_FILE_IDS = {};

async function getAssetBytes(env, assetName) {
  const key = assetName.replace(/\.png$/, "");
  if (PHOTO_BYTES[key]) return PHOTO_BYTES[key];
  try {
    if (!env.ASSETS) return null;
    const res = await env.ASSETS.fetch(new Request("https://assets.local/" + assetName));
    if (!res.ok) {
      await discardBody(res);
      return null;
    }
    const bytes = new Uint8Array(await res.arrayBuffer());
    if (!bytes.length) return null;
    PHOTO_BYTES[key] = bytes;
    return bytes;
  } catch { return null; }
}

async function getCachedPhotoFileId(env, key) {
  if (PHOTO_FILE_IDS[key]) return PHOTO_FILE_IDS[key];
  try {
    const row = await env.DB.prepare("SELECT file_id FROM photo_cache WHERE key = ?").bind(key).first();
    if (row?.file_id) {
      PHOTO_FILE_IDS[key] = row.file_id;
      return row.file_id;
    }
  } catch {}
  return null;
}

async function rememberPhotoFileId(env, key, fileId) {
  if (!fileId) return;
  PHOTO_FILE_IDS[key] = fileId;
  try {
    await env.DB.prepare("INSERT OR REPLACE INTO photo_cache (key, file_id) VALUES (?, ?)").bind(key, fileId).run();
  } catch {}
}

