async function setOnboarding(env, userId, step, completed = 0) {
  await env.DB.prepare("INSERT INTO onboarding (user_id, step, completed, updated_at) VALUES (?, ?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET step = excluded.step, completed = excluded.completed, updated_at = excluded.updated_at").bind(Number(userId), step, completed, Math.floor(Date.now() / 1000)).run().catch(() => {});
}

async function setSettingFlag(env, userId, field, value) {
  const allowedFields = ["auto_reply", "notify_deleted", "notify_edited", "notify_new_user"];
  if (!allowedFields.includes(field)) return;
  await env.DB.prepare(`UPDATE settings SET ${field} = ? WHERE user_id = ?`).bind(value ? 1 : 0, Number(userId)).run().catch(() => {});
}

