async function getPremiumStatus(env, userId) {
  try {
    const r = await env.DB.prepare("SELECT tier, until_at FROM premium_subs WHERE user_id = ?").bind(Number(userId)).first();
    if (!r) return { active: false, tier: null, until_at: 0 };
    if (r.until_at && r.until_at > Math.floor(Date.now() / 1000)) return { active: true, tier: r.tier, until_at: r.until_at };
    return { active: false, tier: r.tier, until_at: r.until_at || 0 };
  } catch {
    return { active: false, tier: null, until_at: 0 };
  }
}

async function hasPremium(env, userId) {
  if (ROOT_ADMINS.includes(Number(userId))) return true;
  const st = await getPremiumStatus(env, userId);
  return st.active;
}

async function grantPremium(env, userId, tier, days) {
  const until = Math.floor(Date.now() / 1000) + Math.max(1, days) * 86400;
  await env.DB.prepare("INSERT INTO premium_subs (user_id, tier, until_at, created_at) VALUES (?, ?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET tier = excluded.tier, until_at = excluded.until_at").bind(Number(userId), tier, until, Math.floor(Date.now() / 1000)).run();
  return until;
}

async function revokePremium(env, userId) {
  await env.DB.prepare("DELETE FROM premium_subs WHERE user_id = ?").bind(Number(userId)).run().catch(() => {});
}

