async function hasBusinessConnection(env, userId, bot = null) {
  try {
    const r = await env.DB.prepare("SELECT connection_id FROM connections WHERE user_id = ? AND (is_active = 1 OR is_active IS NULL) ORDER BY connected_at DESC LIMIT 1").bind(Number(userId)).first();
    if (!r?.connection_id) return false;
    if (bot) {
      try {
        const live = await bot.api.getBusinessConnection(r.connection_id);
        if (!live || live.is_enabled === false) {
          await env.DB.prepare("UPDATE connections SET is_active = 0 WHERE connection_id = ?").bind(r.connection_id).run().catch(() => {});
          invalidateAllowedCache();
          return false;
        }
      } catch {}
    }
    return true;
  } catch { return false; }
}

async function doLs(ctx, env, argStr) {
  const parts = String(argStr || "").trim().split(" ").filter(Boolean);
  let page = 0;
  let filter = "";
  if (parts.length && /^\d+$/.test(parts[parts.length - 1])) page = Math.max(0, parseInt(parts.pop(), 10) - 1);
  if (parts.length) filter = parts[0];
  const key = pagerPut({ mod: "ls", per: 20, owner: ctx.from?.id, ownerId: ctx.from?.id, filter });
  const r = await renderLsPage(env, ctx.from?.id, page, 20, filter);
  const e = pagerGet(key);
  e.page = r.page;
  e.pages = r.total;
  return ctx.reply(r.text, { parse_mode: "HTML", link_preview_options: { is_disabled: true }, reply_markup: r.total > 1 ? pagerKeyboard(key, r.page, r.total) : undefined });
}

