function helpAllCommandsText() {
  let out = `\ud83d\udce6 <b>ВСЕ КОМАНДЫ (${HELP_CATALOG.reduce((n, g) => n + g.items.length, 0)})</b>\n`;
  for (const group of HELP_CATALOG) {
    out += `\n${group.icon} <b>${escapeHtml(group.name)}</b>\n`;
    for (const item of group.items) out += `<code>${item[0]}</code> `;
    out += `\n`;
  }
  out += `\n<i>/help команда — описание • /help 1…${helpTotalPages()} — раздел</i>`;
  return out;
}
function helpCategories() {
  return HELP_CATALOG.map((g, i) => ({ ...g, index: i }));
}

function helpTotalPages() {
  return HELP_CATALOG.length;
}

function helpFindCommand(query) {
  const q = String(query || "").trim().toLowerCase().replace(/^\//, "").replace(/@.*$/, "");
  if (!q) return null;
  for (const group of HELP_CATALOG) {
    for (const item of group.items) {
      const name = item[0].slice(1).toLowerCase();
      if (name === q) return { group, cmd: item[0], desc: item[1] };
    }
  }
  for (const group of HELP_CATALOG) {
    for (const item of group.items) {
      const name = item[0].slice(1).toLowerCase();
      if (name.startsWith(q) || q.startsWith(name)) return { group, cmd: item[0], desc: item[1] };
    }
  }
  return null;
}

function helpCategoryText(index) {
  const group = HELP_CATALOG[index];
  if (!group) return null;
  let out = `${group.icon} <b>${escapeHtml(group.name)}</b>\n`;
  for (const item of group.items) out += `• <code>${item[0]}</code> — ${escapeHtml(item[1])}\n`;
  return out;
}

function helpCategoryList(index) {
  const group = HELP_CATALOG[index];
  if (!group) return null;
  const names = group.items.map(i => `<code>${i[0]}</code>`).join("  ");
  return `${group.icon} <b>${escapeHtml(group.name)}</b>\n${names}`;
}

function getHelpPageText(index) {
  const total = helpTotalPages();
  const page = Math.max(0, Math.min(total - 1, index || 0));
  const body = helpCategoryText(page) || "";
  const nav = page + 1 < total ? `\n<i>Раздел ${page + 1}/${total} • /help ${page + 2} — дальше • /help — оглавление</i>` : `\n<i>Раздел ${page + 1}/${total} • /help 1 — в начало</i>`;
  return { text: body + nav, page, total };
}

function helpKeyboard(page, total) {
  const rows = [];
  const nav = [];
  if (page > 0) nav.push({ text: "\u2b05\ufe0f Назад", callback_data: `helppg:${page - 1}` });
  if (page + 1 < total) nav.push({ text: "\ud83d\udc49\ufe0f", callback_data: `helppg:${page + 1}` });
  if (nav.length) rows.push(nav);
  rows.push([{ text: "\ud83d\udccb Оглавление", callback_data: "helpmenu" }]);
  return { inline_keyboard: rows };
}
const HELP_QUICK_GROUPS = ["Поиск и инструменты", "Музыка и видео", "AI и текст", "Сообщения и архив", "Текстовые функции"];

function getHelpMenuText() {
  const total = HELP_CATALOG.reduce((n, g) => n + g.items.length, 0);
  let out = `🛠 <b>ВСПОМОГАТЕЛЬНЫЕ</b>\n───────────────────────\n`;
  out += `<i>Жми кнопку — бот спросит нужное и выполнит команду. Всего команд в боте: <b>${total}</b></i>\n`;
  for (const name of HELP_QUICK_GROUPS) {
    const group = HELP_CATALOG.find((g) => g.name === name);
    if (!group) continue;
    out += `\n${group.icon} <b>${escapeHtml(group.name)}</b>\n`;
    group.items.slice(0, 10).forEach(([cmd, desc]) => {
      out += `<code>${escapeHtml(cmd)}</code> — ${escapeHtml(desc)}\n`;
    });
    if (group.items.length > 10) out += `<i>…и ещё ${group.items.length - 10} — кнопка «📖 ВСЕ КОМАНДЫ»</i>\n`;
  }
  out += `\n<b>📖 Все команды:</b> <code>/help</code> или <code>/help команда</code>`;
  return out;
}

