/**
 * Same gate the blocked commands use: root + allowed users. Friends and
 * non-beta users must never be offered the admin/archive sections.
 */
async function canUseAdminMenu(env, uid) {
  if (!uid) return false;
  if (ROOT_ADMINS.includes(uid)) return true;
  try { return !!(await isAllowed(env, uid)); } catch { return false; }
}

function getFuncMenuText(canAdmin = false) {
  if (!canAdmin) {
    return `⚙️ <b>Функционал бота</b>\n───────────────────────\n\nВыберите раздел:`;
  }
  return `⚙️ <b>Функционал бота</b>\n───────────────────────\n\n🛡 <b>ПАНЕЛЬ УПРАВЛЕНИЯ [${BOT_NAME}]</b>\n\nВыберите раздел:`;
}

