const SC_CLIENT_IDS = [
  "Pb72ranhoyt6gw7hM7TkzUItXlMWSNSo",
  "iZIs9mchVcX5lhVRyQGGAYlNPVldzAo",
  "a3e059563d7fd3372b49b37a077680e5"
];
const SC_HEADERS = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36",
  "Accept": "application/json, text/javascript, */*; q=0.01",
  "Accept-Language": "ru-RU,ru;q=0.9,en;q=0.8",
  "Origin": "https://soundcloud.com",
  "Referer": "https://soundcloud.com/"
};
const SC_APP_PARAMS = "&app_version=1790019589&app_locale=en";

function scHeaders(env) {
  const h = { ...SC_HEADERS };
  if (env.SC_OAUTH) h["Authorization"] = env.SC_OAUTH;
  return h;
}

async function fetchJsonTimeout(url, ms, options = {}) {
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), ms);
  let res = null;
  try {
    res = await fetch(url, { ...options, signal: ctl.signal });
    clearTimeout(t);
    if (!res.ok) {
      await discardBody(res);
      return null;
    }
    return await res.json().catch(() => null);
  } catch {
    if (res) await discardBody(res);
    return null;
  }
  finally { clearTimeout(t); }
}

async function discardBody(res) {
  try {
    if (res && res.body) await res.body.cancel();
  } catch {}
}

const SC_SEARCH_PATHS = ["/search/sounds", "/search"];

let SC_DYNAMIC_CID = null;
let SC_DYNAMIC_AT = 0;

async function scFreshClientId(env) {
  const now = Date.now();
  if (SC_DYNAMIC_CID && now - SC_DYNAMIC_AT < 6 * 3600 * 1000) return SC_DYNAMIC_CID;
  try {
    const html = await fetchTextWithTimeout("https://soundcloud.com/", 2000);
    if (!html) return SC_DYNAMIC_CID;
    const scripts = [...html.matchAll(/<script[^>]+src="([^"]+\.js[^"]*)"/g)].map(m => m[1]).slice(-2);
    for (const src of scripts.reverse()) {
      try {
        const jsUrl = src.startsWith("http") ? src : "https://soundcloud.com" + src;
        const js = await fetchTextWithTimeout(jsUrl, 2000);
        if (!js) continue;
        const m = js.match(/client_id["']?\s*[:=]\s*["']([a-zA-Z0-9]{20,40})["']/) || js.match(/client_id=([a-zA-Z0-9]{20,40})/);
        if (m?.[1]) {
          SC_DYNAMIC_CID = m[1];
          SC_DYNAMIC_AT = now;
          return SC_DYNAMIC_CID;
        }
      } catch {}
    }
  } catch {}
  return SC_DYNAMIC_CID;
}

function scTrackFromItem(t) {
  if (!t?.title) return null;
  const prog = (t.media?.transcodings || []).find(x => x?.format?.protocol === "progressive");
  return {
    title: t.title,
    artist: t.user?.username || "SoundCloud",
    link: t.permalink_url || "",
    artwork: (t.artwork_url || "").replace("-large", "-t500x500"),
    duration: t.duration ? Math.round(t.duration / 1000) : 0,
    streamUrl: prog?.url || null,
    trackAuth: t.track_authorization || null
  };
}

async function searchSoundCloud(env, query, offset = 0, limit = 8) {
  const q = (query || "").trim().slice(0, 150);
  const start = Math.max(0, parseInt(offset) || 0);
  const cap = Math.max(1, Math.min(50, parseInt(limit) || 8));
  if (q.length < 2) return { tracks: [], cid: null, nextOffset: start };
  const searchWithCid = async (cid) => {
    const attempts = SC_SEARCH_PATHS.map(async (path) => {
      const data = await fetchJsonTimeout(`https://api-v2.soundcloud.com${path}?q=${encodeURIComponent(q)}&client_id=${cid}&limit=${cap}&offset=${start}&linked_partitioning=1${SC_APP_PARAMS}`, 5000, {
        headers: scHeaders(env)
      });
      const out = [];
      for (const raw of data?.collection || []) {
        if (raw?.kind && raw.kind !== "track") continue;
        const track = scTrackFromItem(raw);
        if (track) out.push(track);
        if (out.length >= cap) break;
      }
      if (!out.length) throw new Error("empty");
      return { tracks: out, cid, nextOffset: start + out.length };
    });
    return Promise.any(attempts);
  };
  const knownCids = [...new Set([SC_DYNAMIC_CID, ...SC_CLIENT_IDS].filter(Boolean))];
  try {
    return await Promise.any(knownCids.map(searchWithCid));
  } catch {}
  const fresh = await scFreshClientId(env).catch(() => null);
  if (fresh && !knownCids.includes(fresh)) {
    try {
      return await searchWithCid(fresh);
    } catch {}
  }
  return { tracks: [], cid: null, nextOffset: start };
}

async function resolveScStream(env, track, cid) {
  try {
    if (!track?.streamUrl || !cid) return null;
    const sep = track.streamUrl.includes("?") ? "&" : "?";
    let url = track.streamUrl + sep + "client_id=" + cid;
    if (track.trackAuth) url += "&track_authorization=" + encodeURIComponent(track.trackAuth);
    const d = await fetchJsonTimeout(url, 5000, { headers: scHeaders(env) });
    return d?.url || null;
  } catch { return null; }
}

async function getListsText(env, ownerId) {
  const black = await env.DB.prepare("SELECT target_id, target_name FROM lists WHERE owner_id = ? AND list_type = 'black' ORDER BY added_at DESC").bind(ownerId).all().catch(() => ({ results: [] }));
  const white = await env.DB.prepare("SELECT target_id, target_name FROM lists WHERE owner_id = ? AND list_type = 'white' ORDER BY added_at DESC").bind(ownerId).all().catch(() => ({ results: [] }));
  let out = `📋 <b>Списки фильтра автоответчика</b>\n───────────────────────\n<b>⬛ Чёрный (${black.results?.length || 0}):</b>\n`;
  for (const r of (black.results || [])) out += `• ${escapeHtml(r.target_name || "")} — <code>${r.target_id}</code>\n`;
  out += `\n<b>⬜ Белый (${white.results?.length || 0}):</b>\n`;
  for (const r of (white.results || [])) out += `• ${escapeHtml(r.target_name || "")} — <code>${r.target_id}</code>\n`;
  out += `\nДобавить: <code>/blacklist @ник</code>, <code>/whitelist @ник</code>\nУбрать: <code>/unblacklist @ник</code>, <code>/unwhitelist @ник</code>`;
  return out;
}

async function doTranslate(ctx, env, lang, src) {
  if (!lang || !src) {
    await ctx.reply("❌ Формат: <code>/tr en текст</code> (en, ru, es, de, fr...)", { parse_mode: "HTML" });
    return;
  }
  try {
    const t = await aiShort(env, `Переведи текст на язык "${lang}". Верни ТОЛЬКО перевод, без пояснений.`, src, 2000);
    await ctx.reply(`🌐 <b>Перевод (${escapeHtml(lang)}):</b>\n${escapeHtml(t)}`, { parse_mode: "HTML" });
  } catch (e) {
    await ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
  }
}

