function getFuncManageText(isRoot) {
  let t = `⚙️ <b>Управление</b>\n───────────────────────\n` +
    `• <code>/settings</code> — Настройки уведомлений\n` +
    `• <code>/delmsg &lt;chat_id&gt; &lt;msg_id&gt;</code> — Удалить сообщение из базы\n` +
    `• <code>/clearchat &lt;id|@ник&gt;</code> — Очистить чат\n` +
    `• <code>/whois</code> | <code>/people</code> — пользователи\n` +
    `• <code>/addpeople &lt;id|@ник&gt;</code> — выдать доступ\n` +
    `• <code>/delpeople &lt;id|@ник&gt; [причина]</code> — забрать доступ навсегда (не вернётся после обновления)\n` +
    `• <code>/unblock &lt;id&gt;</code> | <code>/blocklist</code> | <code>/check &lt;id&gt;</code> — бан-лист и проверка\n` +
    `• <code>/connect</code> — статус Business-подключения и инструкция\n` +
    `• <code>/privacy</code> — кто скрыт от чужих уведомлений\n\n` +
    `<b>🛠 Хелперы:</b>\n` +
    `• <code>/search google|yandex|duck|bing &lt;запрос&gt;</code> — веб-поиск\n` +
    `• <code>/blacklist|/whitelist &lt;id|@ник&gt;</code> — фильтры автоответа\n` +
    `• <code>/lists</code> — показать списки\n` +
    `• <code>/autoreply on|off</code> — автоответчик\n` +
    `• <code>/cooldown &lt;мин&gt;</code> — задержка\n\n` +
    `<b>👮 Модерация чатов (в группе):</b>\n` +
    `• <code>/mute</code> <code>/unmute</code> <code>/mutelist</code>\n` +
    `• <code>/warn</code> (x3 = мут) <code>/unwarn</code> <code>/warnlist</code>\n` +
    `• <code>/kick</code> <code>/ban</code> <code>/unban</code>\n` +
    `• <code>/pin</code> <code>/unpin</code> (ответом) <code>/admins</code>\n` +
    `• <code>/info</code> <code>/id</code> <code>/stats</code>`;
  if (isRoot) {
    t += `\n\n👑 <b>Root Панель:</b> <code>/admin</code>\n✉️ <b>Отправить сообщение:</b> <code>/send &lt;id&gt; &lt;текст&gt;</code>\n📋 <b>Заявки:</b> <code>/beta</code>\n` +
      `🔍 <code>/selftest</code> — самопроверка бота\n` +
      `📣 <code>/broadcast текст</code> — рассылка тестерам\n` +
      `📊 <code>/digest</code> | <code>/topchats</code> | <code>/warnlog</code> — сводки\n` +
      `💾 <code>/backup</code> — JSON-дамп базы файлом\n` +
      `🧹 <code>/cleanup</code> — чистка мусора | 🗄 <code>/dbstats</code> — размеры таблиц\n` +
      `✂️ <code>/prune 30</code> — удалить старое из архива | 🪙 <code>/richest</code> — богачи`;
  }
  return t;
}

