function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}
function withTimeout(promise, ms, fallback = null) {
  return Promise.race([
    promise,
    new Promise((resolve) => setTimeout(() => resolve(fallback), ms))
  ]);
}

