function stripHtmlToText(html) {
  let t = String(html || "");
  t = t.replace(/<script[\s\S]*?<\/script>/gi, " ");
  t = t.replace(/<style[\s\S]*?<\/style>/gi, " ");
  t = t.replace(/<noscript[\s\S]*?<\/noscript>/gi, " ");
  t = t.replace(/<!--[\s\S]*?-->/g, " ");
  t = t.replace(/<br\s*\/?>/gi, "\n");
  t = t.replace(/<\/(p|div|li|h[1-6]|tr|section)>/gi, "\n");
  t = t.replace(/<[^>]+>/g, " ");
  const entities = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", mdash: "\u2014", ndash: "\u2013", laquo: "\u00AB", raquo: "\u00BB" };
  t = t.replace(/&([a-z]+);/gi, (m, n) => entities[n.toLowerCase()] ?? " ");
  t = t.replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)));
  t = t.replace(/[ \t]+/g, " ");
  t = t.replace(/\n{3,}/g, "\n\n");
  return t.trim();
}

function extractTitle(html) {
  const m = String(html || "").match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (!m) return "";
  return stripHtmlToText(m[1]).slice(0, 200);
}

function extractMetaDesc(html) {
  const m = String(html || "").match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i)
    || String(html || "").match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i);
  return m ? stripHtmlToText(m[1]).slice(0, 400) : "";
}

function normalizeUrl(raw) {
  let u = String(raw || "").trim();
  if (!u) return "";
  u = u.replace(/^["'<(\s]+|["'>)\s]+$/g, "");
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  try {
    const parsed = new URL(u);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return "";
    return parsed.toString();
  } catch { return ""; }
}

function urlLooksLikeSite(q) {
  const t = String(q || "").trim();
  if (!t) return null;
  if (/^https?:\/\//i.test(t)) return normalizeUrl(t);
  const m = t.match(/\b((?:[\w-]+\.)+[a-z]{2,}(?:\/[^\s]*)?)\b/i);
  if (!m) return null;
  const host = m[1].split("/")[0];
  if (/^(?:[\w-]+\.)*[a-z0-9-]+\.(ru|com|net|org|io|dev|app|me|tv|xyz|info|site|online|store|pro|cc|by|kz|ua|bel|gg|pw|su|uz|md|lv|lt|ee|cz|pl|de|fr|uk)$/i.test(host)) {
    return normalizeUrl(m[1]);
  }
  return null;
}

function siteNameOnly(q) {
  const m = String(q || "").match(/\b((?:[\w-]+\.)+[a-z]{2,})/i);
  return m ? m[1] : String(q || "");
}

async function fetchPageText(url, maxChars = 6000) {
  const target = normalizeUrl(url);
  if (!target) return null;
  const bare = String(target).replace(/^https?:\/\//i, "");
  const candidates = [];
  if (/^https:/i.test(target)) {
    candidates.push(target);
    candidates.push("http://" + bare);
  } else {
    candidates.push(target);
    candidates.push("https://" + bare);
  }

  const headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "ru-RU,ru;q=0.9,en;q=0.8"
  };

  let lastError = "неизвестно";
  for (const attempt of candidates) {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 12000);
    try {
      const res = await fetch(attempt, { signal: ctl.signal, redirect: "follow", headers });
      if (res.ok) {
        const ct = res.headers.get("content-type") || "";
        if (!/text\/html|text\/plain|application\/xhtml/i.test(ct)) {
          lastError = "не HTML (" + ct.split(";")[0] + ")";
          continue;
        }
        const html = await res.text();
        const text = stripHtmlToText(html);
        return {
          url: res.url || attempt,
          status: res.status,
          title: extractTitle(html),
          desc: extractMetaDesc(html),
          text: text.slice(0, maxChars),
          total: text.length
        };
      }
      lastError = "HTTP " + res.status;
      if (res.status !== 403 && res.status !== 404 && !/^5\d\d$/.test(String(res.status))) continue;
    } catch (e) {
      const cause = e?.cause?.code || e?.cause?.message || "";
      const msg = String(e?.message || e);
      lastError = cause ? msg + " (" + cause + ")" : msg;
      lastError = lastError.slice(0, 140);
    } finally {
      clearTimeout(timer);
    }
  }
  return { url: target, error: lastError };
}

function pageContextText(page) {
  if (!page) return "";
  if (page.error) return `Страница ${page.url} НЕДОСТУПНА: ${page.error}\nВАЖНО: ты её не открыл и текста не видел. НЕ ВЫДУМЫВАЙ содержимое, разделы, цифры и цитаты. Просто скажи, что не смог открыть сайт.\n`;
  const parts = [`Содержимое страницы ${page.url} (заголовок: ${page.title || "без заголовка"}):`];
  if (page.desc) parts.push(`Описание: ${page.desc}`);
  parts.push(page.text || "(текста нет)");
  return parts.join("\n").slice(0, 6500);
}

const CHAT_Q_HINTS = [
  new RegExp("с кем я общаюсь", "i"),
  new RegExp("с кем я сейчас общаюсь", "i"),
  new RegExp("с кем я говорю", "i"),
  new RegExp("с кем сейчас говорю", "i"),
  new RegExp("с кем ты сейчас общаешься", "i"),
  new RegExp("кого я пишу", "i"),
  new RegExp("кому я пишу", "i"),
  new RegExp("что мы обсуждаемся", "i"),
  new RegExp("о чём мы говорим", "i"),
  new RegExp("как этот чат называется", "i"),
  new RegExp("чей это чат", "i"),
  new RegExp("чей чат", "i"),
  new RegExp("дайди", "i"),
  new RegExp("даиди", "i"),
  new RegExp("ком у меня идёт", "i"),
  new RegExp("как зовут собеседника", "i"),
  new RegExp("с кем я переписываюсь", "i")
];

function looksLikeChatQuestion(q) {
  const t = String(q || "");
  return CHAT_Q_HINTS.some((re) => re.test(t));
}

async function chatContextText(env, ownerId, chatId, maxChars = 5000) {
  try {
    const rows = await env.DB.prepare(
      "SELECT user_id, username, full_name, is_outgoing, text, media_type, sent_at FROM messages WHERE owner_id = ? AND chat_id = ? ORDER BY sent_at DESC LIMIT 40"
    ).bind(ownerId, chatId).all();
    if (!rows.results?.length) return "";
    const list = rows.results.slice().reverse();
    const partner = list.find((m) => !m.is_outgoing);
    const who = partner
      ? `${partner.full_name || "Собеседник"}${partner.username ? " (@" + partner.username + ")" : ""} [ID ${partner.user_id}]`
      : "неизвестно";
    let out = `Данные по текущему чату:\nСобеседник: ${who}\nСообщений в архиве: ${list.length}\n\nПоследние сообщения:\n`;
    for (const m of list) {
      const d = new Date(m.sent_at * 1000).toLocaleString("ru-RU", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
      const who2 = m.is_outgoing ? "Владелец" : "Собеседник";
      const body = m.text || `[${m.media_type || "медиа"}]`;
      out += `[${d}] ${who2}: ${String(body).slice(0, 300)}\n`;
    }
    return out.slice(0, maxChars);
  } catch { return ""; }
}

async function contactsContextText(env, ownerId, maxChars = 3000) {
  try {
    const rows = await env.DB.prepare(
      "SELECT user_id, username, full_name, COUNT(*) as c FROM messages WHERE owner_id = ? GROUP BY user_id ORDER BY c DESC LIMIT 12"
    ).bind(ownerId).all();
    if (!rows.results?.length) return "";
    let out = "Ближайшие контакты по количеству сообщений:\n";
    rows.results.forEach((r) => {
      out += `• ${r.full_name || "Без имени"}${r.username ? " @" + r.username : ""} — ID ${r.user_id} (${r.c} сообщений)\n`;
    });
    return out.slice(0, maxChars);
  } catch { return ""; }
}

async function buildAiContext(env, question, opts = {}) {
  const q = String(question || "");
  const ownerId = Number(opts.ownerId || 0);
  const chatId = Number(opts.chatId || 0);
  const blocks = [];
  let usedPage = false;
  let usedChat = false;

  if (urlLooksLikeSite(q)) {
    const site = urlLooksLikeSite(q);
    const page = await fetchPageText(site);
    if (page && !page.error) { blocks.push(pageContextText(page)); usedPage = true; }
    else if (page) { blocks.push(pageContextText(page)); }
  }

  if (ownerId && chatId && looksLikeChatQuestion(q)) {
    const chat = await chatContextText(env, ownerId, chatId);
    if (chat) { blocks.push(chat); usedChat = true; }
    const contacts = await contactsContextText(env, ownerId);
    if (contacts) blocks.push(contacts);
  }

  const search = await getSearchContext(q);
  if (search) blocks.push(search);

  return { text: blocks.join("\n\n"), usedPage, usedChat, usedSearch: !!search };
}

