async function aiRoastEnabled(env, ownerId) {
  try {
    const r = await env.DB.prepare("SELECT ai_roast FROM settings WHERE user_id = ?").bind(ownerId).first();
    if (r && r.ai_roast !== null && r.ai_roast !== undefined) return Number(r.ai_roast) === 1;
  } catch {}
  return true;
}

async function aiRoastSet(env, ownerId, on) {
  try {
    await env.DB.prepare("INSERT OR IGNORE INTO settings (user_id) VALUES (?)").bind(ownerId).run();
    await env.DB.prepare("UPDATE settings SET ai_roast = ? WHERE user_id = ?").bind(on ? 1 : 0, ownerId).run();
  } catch {}
}

const ROAST_SYSTEM =
  "\n\nТОНАЛЬНОСТЬ: пользователь разрешил подколы. Ты можешь мягко прожарить его или собеседника," +
  " пошутить и подколоть — БЕЗ оскорблений по здоровью, родным, национальности и без угроз." +
  " Юмор добрый, как у друзей. Если просят серьёзно — отвечай серьёзно." +
  "\nЕсли человек назвал стиль, персонажа или манеру — ДЕРЖИСЯ ЭТОГО СТИЛЯ буквально: характерные реплики," +
  " обращения, лексика. Не превращай это в общие советы и не пересказывай содержание сериала.";

function buildRoastPrompt(q, opts = {}) {
  const who = String(opts.name || "").trim();
  const style = String(opts.style || "").trim();
  const lines = [
    "",
    "СЕЙЧАС ПОЛЬЗОВАТЕЛЬ ПРОСИТ, ЧТОБЫ ТЫ НАХАМИЛ / ПОДКОЛИЛ. Это его собственный бот, он нормально воспринимает.",
    "ОТВЕТЬ СРАЗУ РОСТОМ. Никаких вступлений, извинений, советов и объяснений."
  ];
  if (who) lines.push(`ОБРАЩАЙСЯ К НЕМУ ПО НИКУ: «${who}». Ник обязателен, упомяни его в тексте.`);
  if (style) lines.push(`СТИЛЬ, КОТОРЫЙ ОН ЗАПРОСИЛ: «${style}». Обращайся к нему именно так — с характерной лексикой и манерой этого персонажа.`);
  lines.push("ДЛИНА: 1-4 предложения. Можно матерно и по-братски. Главное — смешно и в стиле, а не полезно.");
  lines.push("");
  lines.push("ЗАПРОС: " + q);
  return lines.join("\n");
}

async function aiJokeAnswer(env, question, opts = {}) {
  const roastOn = opts.roast === undefined ? await aiRoastEnabled(env, opts.ownerId || 0) : opts.roast;
  const base = await aiSmart(env, question, { ...opts, extraSystem: roastOn ? ROAST_SYSTEM : "", extraUser: roastOn ? buildRoastPrompt(question, opts.roastOpts) : "" });
  return { text: base, roast: roastOn };
}

