function isRootOwner(ownerId) {
  return isRootId(ownerId);
}

// Friends get every command EXCEPT the ones that expose the owner's private data.
const BIZ_FRIEND_BLOCK = new Set([
  "/read", "/ls", "/dox", "/osint", "/finduser", "/find", "/summary", "/short", "/info",
  "/history", "/allhistory", "/deleted", "/edits", "/export", "/redact", "/delmsg",
  "/edit", "/editall", "/save", "/del", "/hide", "/clearhistory",
  "/spend", "/earn", "/budget", "/finmonth", "/fincat", "/fintop", "/finai", "/fin", "/finance",
  "/taskadd", "/today", "/tdone", "/tstart", "/tstats", "/tprojects", "/tai", "/tasks",
  "/note", "/notes", "/ask", "/habit", "/habits", "/goal", "/goals", "/journal", "/mood", "/weekly",
  "/phone", "/phones", "/contacts", "/connect", "/checkconnection", "/autoreply", "/autotext",
  "/mutelist", "/whitelist", "/blacklist", "/lists", "/beta", "/delaccount", "/ban", "/unban",
  "/dns", "/account", "/users", "/stats", "/db"
]);

function bizCommandAllowedFor(ownerId, word) {
  if (isRootOwner(ownerId)) return true;
  if (!word) return false;
  if (BIZ_FRIEND_BLOCK.has(word)) return false;
  const base = String(word).split(" ")[0];
  if (BIZ_FRIEND_BLOCK.has(base)) return false;
  if (/^\/(read|ls|dox|find|fin|task|note|goal|ask)/.test(base)) return false;
  return true;
}

async function getSearchContext(query) {
  try {
    const q = (query || "").trim().slice(0, 200);
    if (q.length < 2) return "";
    let results = await searxSearch(q);
    if (!results.length) results = await searxSearch(siteNameOnly(q));
    if (!results.length) results = await searchEngine("duck", q);
    if (!results.length) results = await searchEngine("mojeek", q);
    if (!results.length) results = await searchEngine("bing", q);
    if (!results.length) return "";
    const today = new Date().toISOString().slice(0, 10);
    let out = `Сегодня ${today}. Актуальные данные из веб-поиска по запросу «${q}»:\n`;
    results.slice(0, 5).forEach((r, idx) => {
      out += `${idx + 1}. ${r.title}${r.snippet ? " — " + r.snippet : ""}\n   Источник: ${r.url}\n`;
    });
    out += "\nВАЖНО: это данные ПОИСКОВОЙ ВЫДАЧИ, а не текст самой страницы. Опирайся только на них и прямо скажи, что это выдача поиска, если вопрос был про конкретный сайт.\n";
    return out.slice(0, 2500);
  } catch { return ""; }
}
async function aiAskWithSearch(env, question, preferred = null) {
  const q = String(question || "").slice(0, 2000);
  const context = await getSearchContext(q);
  const userText = context
    ? `Вопрос: ${q}\n\n${context}\n\nОтветь на вопрос, обязательно используя данные поиска выше (цены, характеристики, даты). В конце перечисли источники одной строкой.`
    : q;
  let answer = await runAi(env, [
    { role: "system", content: AI_IDENTITY + " У тебя есть веб-доступ: контекст поиска уже приложен к вопросу, опирайся на него." },
    { role: "user", content: userText.slice(0, 6000) }
  ], preferred);
  if (!answer) answer = "Не смог придумать ответ.";
  if (answer.length > 3300) answer = answer.slice(0, 3250) + "...";
  return withCredit(answer);
}

async function doSearch(ctx, rawEngine, query) {
  const engines = ["google", "yandex", "duck", "bing", "mojeek", "web"];
  let engine = (rawEngine || "web").toLowerCase();
  if (engine === "ya") engine = "yandex";
  if (engine === "ddg") engine = "duck";
  if (!engines.includes(engine)) {
    query = ((rawEngine || "") + " " + (query || "")).trim();
    engine = "web";
  }
  query = (query || "").trim().slice(0, 300);
  if (!query) {
    await ctx.reply("❌ Формат: <code>/search web что искать</code>\nДвижки: web, google, yandex, duck, bing, mojeek", { parse_mode: "HTML" });
    return;
  }
  await ctx.reply(`🔍 <i>Ищу...</i>`, { parse_mode: "HTML" });
  const names = { web: "Веб", google: "Google", yandex: "Яндекс", duck: "DuckDuckGo", bing: "Bing", mojeek: "Mojeek" };
  let results = [];
  let used = engine;
  if (engine === "web") {
    results = await searxSearch(query);
    used = "web";
  } else {
    results = await searchEngine(engine, query);
  }
  const fallbacks = ["web", "duck", "mojeek", "bing"];
  for (const fb of fallbacks) {
    if (results.length) break;
    if (fb === used) continue;
    if (fb === "web") results = await searxSearch(query);
    else results = await searchEngine(fb, query);
    if (results.length) used = fb;
  }
  if (!results.length) {
    await ctx.reply(`🔍 <b>${escapeHtml(query)}</b>\n\n😔 Ничего не нашлось — все движки молчат. Попробуй переформулировать.`, { parse_mode: "HTML" });
    return;
  }
  let out = `🔍 <b>${names[used] || used}: ${escapeHtml(query)}</b>\n───────────────────────\n`;
  results.forEach((r, idx) => { out += `${idx + 1}. <a href="${r.url}">${escapeHtml(r.title)}</a>${r.snippet ? `\n<i>${escapeHtml(r.snippet.slice(0, 140))}</i>` : ""}\n`; });
  if (used !== engine) out += `\n<i>${names[engine]} не ответил — показал ${names[used]}.</i>`;
  try {
    await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  } catch {
    await ctx.reply(out, { parse_mode: "HTML" });
  }
}

async function doYtSearch(ctx, env, query) {
  const q = (query || "").trim().slice(0, 150);
  if (q.length < 2) {
    await ctx.reply("❌ Формат: <code>/yt смешной кот</code>", { parse_mode: "HTML" });
    return;
  }
  await ctx.reply(`🎬 <i>Ищу видео «${escapeHtml(q)}»...</i>`, { parse_mode: "HTML" });
  const yt = await pipedSearch(env, q, "videos").catch(() => ({ tracks: [], base: null }));
  if (!yt.tracks.length) {
    await ctx.reply(`🎬 По запросу «${escapeHtml(q)}» видео не нашлось.`, { parse_mode: "HTML" });
    return;
  }
  const top = yt.tracks[0];
  const mediaUrl = await youtubeMediaUrl(env, top.id, "video");
  const sentVideo = Boolean(await sendVideoRobust(ctx, env, mediaUrl, () => resolveYoutubeMedia(env, top.id, "video"), {
    caption: withCredit(`🎬 <b>${escapeHtml(top.title)}</b> — ${escapeHtml(top.artist)}\n<i>▶️ YouTube • MP4/H.264</i>`),
    parse_mode: "HTML",
    supports_streaming: true
  }));
  if (!sentVideo) console.log(`📡 Не удалось отправить видео — MP4 не подтянулся, открывай по ссылке ниже.`);
  let out = `🎬 <b>Видео по «${escapeHtml(q)}»:</b>\n───────────────────────\n`;
  yt.tracks.forEach((t, i) => {
    const dur = t.duration ? ` (${fmtDur(t.duration)})` : "";
    out += `${i + 1}. <b>${escapeHtml(t.title)}</b> — ${escapeHtml(t.artist)}${dur} (<a href="${t.link}">смотреть</a>)\n`;
  });
  out = withCredit(out);
  try {
    await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  } catch {
    await ctx.reply(out, { parse_mode: "HTML" });
  }
}
