async function tiktokOembed(url) {
  try {
    return await fetchJsonTimeout(`https://www.tiktok.com/oembed?url=${encodeURIComponent(url)}`, 7000);
  } catch {
    return null;
  }
}

async function doTikTok(ctx, env, argStr) {
  const raw = String(argStr || "").trim();
  if (!raw) return ctx.reply("❌ Формат: <code>/tiktok ссылка</code> или <code>/tiktok запрос</code>", { parse_mode: "HTML" });
  const wantsAudio = /\b(audio|sound|музык|звук|mp3)\b/i.test(raw) || /\b(аудио|музыка|звук)\b/i.test(raw);
  const source = supportedMediaSource(raw);
  if (source?.type === "tiktok") {
    const format = wantsAudio ? "audio" : "video";
    if (format === "audio") {
      await ctx.reply(`🎵 <i>Вытаскиваю звук из TikTok...</i>`, { parse_mode: "HTML" });
      const audioUrl = await externalMediaUrl(env, source.url, "audio");
      const meta = await tiktokOembed(source.url);
      const caption = withCredit(`🎵 <b>${escapeHtml(meta?.title || "TikTok sound")}</b>${meta?.author_name ? ` — ${escapeHtml(meta.author_name)}` : ""}\n<i>🎧 Звук из TikTok</i>`);
      const sent = await sendAudioRobust(ctx, env, audioUrl, () => resolveCobaltMedia(env, source.url, "audio"), {
        title: String(meta?.title || "TikTok sound").slice(0, 100),
        performer: String(meta?.author_name || "TikTok").slice(0, 100),
        caption,
        parse_mode: "HTML"
      });
      if (sent) return;
      return ctx.reply(`🎵 Не удалось вытащить звук. Открой оригинал: <a href="${escapeHtml(meta?.url || source.url)}">TikTok</a>`, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
    }
    await ctx.reply(`🎵 <i>Готовлю TikTok MP4...</i>`, { parse_mode: "HTML" });
    const meta = await tiktokOembed(source.url);
    const mediaUrl = await externalMediaUrl(env, source.url, "video");
    await sendVideoRobust(ctx, env, mediaUrl, () => resolveCobaltMedia(env, source.url, "video"), {
      caption: withCredit(`🎵 <b>${escapeHtml(meta?.title || "TikTok")}</b>${meta?.author_name ? ` — ${escapeHtml(meta.author_name)}` : ""}\n<i>TikTok • MP4</i>`),
      parse_mode: "HTML",
      supports_streaming: true
    });
    const link = meta?.url || source.url;
    return ctx.reply(withCredit(`🎵 <b>TikTok:</b> ${meta?.title ? escapeHtml(meta.title) : "видео"}\n<a href="${escapeHtml(link)}">Открыть оригинал</a>\n<i>Только звук: <code>/tiktok ${escapeHtml(source.url)} audio</code></i>`), { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  }
  await ctx.reply(`🔎 <i>Ищу TikTok по «${escapeHtml(raw.slice(0, 100))}»...</i>`, { parse_mode: "HTML" });
  const results = await searxSearch(`${raw} site:tiktok.com`, 1, 5, stableSearchBase(`${raw} site:tiktok.com`)).catch(() => []);
  if (!results.length) {
    return ctx.reply(withCredit(`🔎 <b>TikTok:</b> ${escapeHtml(raw)}\n<a href="https://www.tiktok.com/search?q=${encodeURIComponent(raw)}">Открыть поиск TikTok</a>`), { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  }
  let out = `🎵 <b>TikTok по «${escapeHtml(raw)}»:</b>\n───────────────────────\n`;
  results.forEach((r, i) => { out += `${i + 1}. <a href="${escapeHtml(r.url)}">${escapeHtml(r.title)}</a>\n`; });
  out += `\n<i>Пришли прямую ссылку — кину MP4. Только звук: <code>/tiktok ссылка audio</code>.</i>\n`;
  out += `<i>Ищи самый трендовый звук: <code>/tiktokmusic ${escapeHtml(raw.slice(0, 60))}</code></i>`;
  out = withCredit(out);
  try { await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } }); } catch { await ctx.reply(out, { parse_mode: "HTML" }); }
}

const TIKTOK_SOUND_HINTS = ["sound", "звук", "музыка", "trending sound", "original sound", "audio"];

async function doTikTokMusic(ctx, env, argStr) {
  const raw = String(argStr || "").trim().slice(0, 150);
  if (raw.length < 2) {
    return ctx.reply(withCredit("❌ Формат: <code>/tiktokmusic название звука</code>"), { parse_mode: "HTML" });
  }
  const direct = supportedMediaSource(raw);
  if (direct?.type === "tiktok") return doTikTok(ctx, env, `${raw} audio`);
  await ctx.reply(`🎵 <i>Ищу трендовый звук TikTok по «${escapeHtml(raw)}»...</i>`, { parse_mode: "HTML" });
  const queries = [
    `${raw} site:tiktok.com sound`,
    `${raw} tiktok trending sound`,
    `${raw} site:tiktok.com/@ music`
  ];
  const found = [];
  for (const q of queries) {
    if (found.length >= 6) break;
    const res = await searxSearch(q, 1, 6, stableSearchBase(q)).catch(() => []);
    for (const r of res) {
      if (!r?.url || !/tiktok\.com/i.test(r.url)) continue;
      if (found.some(x => x.url === r.url)) continue;
      found.push(r);
    }
  }
  const sounds = found.filter(r => TIKTOK_SOUND_HINTS.some(h => String(r.title || "").toLowerCase().includes(h)));
  const list = (sounds.length ? sounds : found).slice(0, 8);
  if (!list.length) {
    const searchUrl = `https://www.tiktok.com/search?q=${encodeURIComponent(`${raw} sound`)}`;
    return ctx.reply(withCredit(`🎵 <b>Звук «${escapeHtml(raw)}»:</b>\n😔 Нашёл только поиск. Открой: <a href="${escapeHtml(searchUrl)}">TikTok Sound</a>\n<i>Совет: пришли ссылку на видео с этим звуком — кину MP3.</i>`), { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  }
  let out = `🎵 <b>Звуки TikTok по «${escapeHtml(raw)}»:</b>\n───────────────────────\n`;
  list.forEach((r, i) => {
    const marker = sounds.includes(r) ? "🔊" : "🎬";
    out += `${i + 1}. ${marker} <a href="${escapeHtml(r.url)}">${escapeHtml(String(r.title || "TikTok").slice(0, 70))}</a>\n`;
  });
  out += `\n<i>Скопируй ссылку и кинь: <code>/tiktok ссылка audio</code> — вытащу звук в MP3.</i>`;
  out = withCredit(out);
  try { await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } }); } catch { await ctx.reply(out, { parse_mode: "HTML" }); }
}

async function lookupWikipedia(query) {
  const q = String(query || "").trim().slice(0, 200);
  if (q.length < 2) return null;
  const summary = await fetchJsonTimeout(`https://ru.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(q)}`, 9000);
  if (summary?.extract) {
    return {
      title: summary.title || q,
      extract: String(summary.extract).slice(0, 3200),
      url: summary.content_urls?.desktop?.page || `https://ru.wikipedia.org/wiki/${encodeURIComponent(q.replace(/ /g, "_"))}`
    };
  }
  const search = await fetchJsonTimeout(`https://ru.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(q)}&format=json&origin=*&utf8=1`, 9000);
  const item = search?.query?.search?.[0];
  if (!item?.title) return null;
  return {
    title: item.title,
    extract: "",
    url: `https://ru.wikipedia.org/wiki/${encodeURIComponent(item.title.replace(/ /g, "_"))}`
  };
}

async function doWiki(ctx, argStr) {
  const q = String(argStr || "").trim().slice(0, 200);
  if (!q) { await ctx.reply("❌ Формат: <code>/wiki Python</code>", { parse_mode: "HTML" }); return; }
  await ctx.reply(`📚 <i>Ищу в Википедии...</i>`, { parse_mode: "HTML" });
  const data = await lookupWikipedia(q).catch(() => null);
  if (!data) return ctx.reply("❌ В Википедии ничего не нашлось.", { parse_mode: "HTML" });
  const text = data.extract
    ? `${escapeHtml(data.extract)}\n\n<a href="${escapeHtml(data.url)}">Открыть статью</a>`
    : `Открывай: <a href="${escapeHtml(data.url)}">статья</a>`;
  return ctx.reply(`📚 <b>${escapeHtml(data.title)}</b>\n───────────────────────\n${text}`, { parse_mode: "HTML" });
}

