async function doDict(ctx, argStr) {
  const q = String(argStr || "").trim().slice(0, 100);
  if (!q) { await ctx.reply("❌ Формат: <code>/dict слово</code>", { parse_mode: "HTML" }); return; }
  try {
    const d = await fetchJsonTimeout(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(q)}`, 10000);
    const defs = [];
    for (const entry of (d || [])) for (const m of (entry.meanings || [])) for (const x of (m.definitions || [])) defs.push(`${m.partOfSpeech}: ${x.definition}`);
    if (!defs.length) throw 0;
    let out = `📖 <b>${escapeHtml(q)}</b>\n───────────────────────\n` + defs.slice(0, 5).map(x => `• ${escapeHtml(x)}`).join("\n");
    if ((d[0]?.phonetic || "")) out += `\n🔊 ${escapeHtml(d[0].phonetic)}`;
    await ctx.reply(out, { parse_mode: "HTML" });
  } catch { await ctx.reply("❌ Слово не найдено в английском словаре.", { parse_mode: "HTML" }); }
}

