async function doArxiv(ctx, argStr) {
  const q = String(argStr || "").trim().slice(0, 150);
  if (!q) { await ctx.reply("❌ Формат: <code>/arxiv transformers</code>", { parse_mode: "HTML" }); return; }
  await ctx.reply(`📄 <i>Ищу в arXiv...</i>`, { parse_mode: "HTML" });
  try {
    const res = await fetch(`https://export.arxiv.org/api/query?search_query=all:${encodeURIComponent(q)}&start=0&max_results=5&sortBy=submittedDate&sortOrder=descending`, { signal: AbortSignal.timeout(12000) });
    const xml = await res.text();
    const entries = [...xml.matchAll(/<entry>([\s\S]*?)<\/entry>/g)].slice(0, 5);
    if (!entries.length) throw 0;
    let out = `📄 <b>arXiv: ${escapeHtml(q)}</b>\n───────────────────────\n`;
    for (const [, e] of entries) {
      const title = (e.match(/<title>([\s\S]*?)<\/title>/)?.[1] || "").replace(/\s+/g, " ").trim().slice(0, 150);
      const link = e.match(/<id>([\s\S]*?)<\/id>/)?.[1]?.trim() || "";
      const date = (e.match(/<published>([\s\S]*?)<\/published>/)?.[1] || "").slice(0, 10);
      out += `• <a href="${link}">${escapeHtml(title)}</a> <i>(${date})</i>\n`;
    }
    await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  } catch { await ctx.reply("❌ В arXiv ничего не нашлось.", { parse_mode: "HTML" }); }
}

async function doStackOverflow(ctx, argStr) {
  const q = String(argStr || "").trim().slice(0, 150);
  if (!q) { await ctx.reply("❌ Формат: <code>/so python list comprehension</code>", { parse_mode: "HTML" }); return; }
  await ctx.reply(`🥞 <i>Ищу на Stack Overflow...</i>`, { parse_mode: "HTML" });
  try {
    const d = await fetchJsonTimeout(`https://api.stackexchange.com/2.3/search/advanced?order=desc&sort=votes&q=${encodeURIComponent(q)}&site=stackoverflow&pagesize=5&filter=!nNPvSNVZ7e`, 12000);
    const items = d?.items || [];
    if (!items.length) throw 0;
    let out = `🥞 <b>Stack Overflow: ${escapeHtml(q)}</b>\n───────────────────────\n`;
    for (const it of items) {
      out += `• <a href="${it.link}">${escapeHtml(it.title)}</a> ✅${it.is_answered ? "✔" : "✘"} ⭐${it.score}\n`;
    }
    await ctx.reply(out, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
  } catch { await ctx.reply("❌ На Stack Overflow ничего не нашлось.", { parse_mode: "HTML" }); }
}

async function doTranslateRu(ctx, env, argStr) {
  const q = String(argStr || "").trim().slice(0, 500);
  if (!q) { await ctx.reply("❌ Формат: <code>/tru текст на английском</code>", { parse_mode: "HTML" }); return; }
  try {
    const t = await aiShort(env, `Переведи текст на русский. Верни ТОЛЬКО перевод, без пояснений.`, q, 2000);
    await ctx.reply(`🌐 <b>Перевод (ru):</b>\n${escapeHtml(t)}`, { parse_mode: "HTML" });
  } catch (e) {
    await ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
  }
}

