function fmtPrice(n) {
  if (!isFinite(n)) return "?";
  if (n >= 1000) return n.toLocaleString("ru-RU", { maximumFractionDigits: 0 });
  if (n >= 1) return n.toLocaleString("ru-RU", { maximumFractionDigits: 2 });
  return n.toLocaleString("ru-RU", { maximumFractionDigits: 6 });
}

function calcExpr(src) {
  const s = String(src || "").replace(/\s+/g, "").replace(/,/g, ".").slice(0, 100);
  if (!s || !/^[0-9+\-*/().%^]*$/.test(s)) return null;
  let i = 0;
  function parseExpr() { let v = parseTerm(); while (s[i] === "+" || s[i] === "-") { const op = s[i++]; const r = parseTerm(); v = op === "+" ? v + r : v - r; } return v; }
  function parseTerm() { let v = parsePow(); while (s[i] === "*" || s[i] === "/" || s[i] === "%") { const op = s[i++]; const r = parsePow(); if ((op === "/" || op === "%") && r === 0) throw 0; v = op === "*" ? v * r : op === "/" ? v / r : v % r; } return v; }
  function parsePow() { let v = parseUnary(); if (s[i] === "^") { i++; v = Math.pow(v, parseUnary()); } return v; }
  function parseUnary() { if (s[i] === "-") { i++; return -parseUnary(); } if (s[i] === "+") { i++; return parseUnary(); } return parsePrimary(); }
  function parsePrimary() {
    if (s[i] === "(") { i++; const v = parseExpr(); if (s[i] !== ")") throw 0; i++; return v; }
    let num = "";
    while (i < s.length && /[0-9.]/.test(s[i])) num += s[i++];
    if (!num || num.split(".").length > 2) throw 0;
    return parseFloat(num);
  }
  try {
    const v = parseExpr();
    if (i !== s.length || !isFinite(v)) return null;
    return Math.round(v * 1e10) / 1e10;
  } catch { return null; }
}

