async function doCrypto(ctx, coinArg) {
  const key = (String(coinArg || "").trim().split(" ")[0] || "btc").toLowerCase();
  const sym = COIN_MAP[key] || key.toUpperCase().replace(/[^A-Z]/g, "").slice(0, 10) || "BTC";
  try {
    const res = await fetch(`https://api.binance.com/api/v3/ticker/24hr?symbol=${sym}USDT`);
    if (!res.ok) throw 0;
    const d = await res.json();
    const price = parseFloat(d.lastPrice);
    const chg = parseFloat(d.priceChangePercent);
    const arrow = chg >= 0 ? "📈" : "📉";
    await ctx.reply(`${arrow} <b>${sym}/USDT:</b> $${fmtPrice(price)} (<b>${chg >= 0 ? "+" : ""}${chg.toFixed(2)}%</b> за 24ч)`, { parse_mode: "HTML" });
  } catch {
    await ctx.reply("❌ Не нашёл такую монету. Пример: <code>/crypto btc</code>, <code>/crypto ton</code>", { parse_mode: "HTML" });
  }
}

async function doRate(ctx) {
  try {
    const res = await fetch("https://api.frankfurter.app/latest?from=USD&to=RUB,EUR,CNY");
    if (!res.ok) throw 0;
    const d = await res.json();
    const usdRub = d.rates?.RUB, eurUsd = d.rates?.EUR, cnyUsd = d.rates?.CNY;
    if (!usdRub) throw 0;
    const eurRub = usdRub / eurUsd, cnyRub = usdRub / cnyUsd;
    await ctx.reply(`💱 <b>Курсы (${escapeHtml(d.date || "сегодня")}):</b>\n───────────────────────\n🇺🇸 USD/RUB: <b>${fmtPrice(usdRub)} ₽</b>\n🇪🇺 EUR/RUB: <b>${fmtPrice(eurRub)} ₽</b>\n🇨🇳 CNY/RUB: <b>${fmtPrice(cnyRub)} ₽</b>`, { parse_mode: "HTML" });
  } catch {
    await ctx.reply("❌ Не смог получить курсы.", { parse_mode: "HTML" });
  }
}

async function geocodeCity(city) {
  try {
    const res = await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1&language=ru&format=json`);
    if (!res.ok) {
      await discardBody(res);
      return null;
    }
    const d = await res.json().catch(() => null);
    const r = d?.results?.[0];
    return r ? { name: r.name, country: r.country || "", lat: r.latitude, lon: r.longitude, tz: r.timezone } : null;
  } catch { return null; }
}

async function doWeather(ctx, cityArg) {
  const city = (cityArg || "").trim().slice(0, 100);
  if (!city) {
    await ctx.reply("❌ Формат: <code>/weather Москва</code>", { parse_mode: "HTML" });
    return;
  }
  const g = await geocodeCity(city);
  if (!g) {
    await ctx.reply(`❌ Город «${escapeHtml(city)}» не найден.`, { parse_mode: "HTML" });
    return;
  }
  try {
    const res = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${g.lat}&longitude=${g.lon}&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min&timezone=auto`);
    if (!res.ok) throw 0;
    const d = await res.json();
    const c = d.current, day = d.daily;
    const desc = WMO_RU[c.weather_code] || "—";
    await ctx.reply(
      `🌤️ <b>${escapeHtml(g.name)}${g.country ? ", " + escapeHtml(g.country) : ""}</b>\n───────────────────────\n${desc}\n` +
      `🌡️ ${c.temperature_2m}°C (ощущается ${c.apparent_temperature}°C)\n` +
      `📈 Днём до ${day.temperature_2m_max?.[0]}°C, ночью ${day.temperature_2m_min?.[0]}°C\n` +
      `💧 Влажность: ${c.relative_humidity_2m}% | 💨 Ветер: ${c.wind_speed_10m} км/ч`,
      { parse_mode: "HTML" }
    );
  } catch {
    await ctx.reply("❌ Не смог получить погоду.", { parse_mode: "HTML" });
  }
}

