async function doShort(ctx, url) {
  const u = (url || "").trim().split(" ")[0] || "";
  if (!/^https?:\/\/.+\..+/.test(u)) {
    await ctx.reply("❌ Формат: <code>/short https://site.com/xxx</code>", { parse_mode: "HTML" });
    return;
  }
  try {
    const res = await fetch(`https://is.gd/create.php?format=simple&url=${encodeURIComponent(u)}`);
    const short = (await res.text()).trim();
    if (!res.ok || !short.startsWith("https://")) throw 0;
    await ctx.reply(`🔗 Короткая ссылка:\n<code>${escapeHtml(short)}</code>`, { parse_mode: "HTML" });
  } catch {
    await ctx.reply("❌ Не смог сократить.", { parse_mode: "HTML" });
  }
}

async function doDns(ctx, host) {
  let h = (host || "").trim().split(" ")[0].replace(/^https?:\/\//i, "").split("/")[0] || "";
  if (!h || !h.includes(".")) {
    await ctx.reply("❌ Формат: <code>/dns google.com</code>", { parse_mode: "HTML" });
    return;
  }
  try {
    const res = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(h)}&type=A`);
    if (!res.ok) throw 0;
    const d = await res.json();
    const ips = (d.Answer || []).filter(a => a.type === 1).map(a => a.data);
    if (!ips.length) throw 0;
    await ctx.reply(`🌐 <b>${escapeHtml(h)}</b>:\n<code>${ips.slice(0, 8).join("\n")}</code>`, { parse_mode: "HTML" });
  } catch {
    await ctx.reply("❌ Ничего не нашлось.", { parse_mode: "HTML" });
  }
}

async function doConvert(ctx, argStr) {
  const parts = String(argStr || "").trim().split(/\s+/).filter(Boolean);
  if (parts.length < 3) {
    await ctx.reply("❌ Формат: <code>/convert 100 usd rub</code>", { parse_mode: "HTML" });
    return;
  }
  const amount = parseFloat(parts[0].replace(",", "."));
  const from = parts[1].toUpperCase().replace(/[^A-Z]/g, "").slice(0, 5);
  const to = parts[2].toUpperCase().replace(/[^A-Z]/g, "").slice(0, 5);
  if (!isFinite(amount) || !from || !to) {
    await ctx.reply("❌ Формат: <code>/convert 100 usd rub</code>", { parse_mode: "HTML" });
    return;
  }
  try {
    const res = await fetch(`https://api.frankfurter.app/latest?amount=${amount}&from=${from}&to=${to}`);
    if (!res.ok) throw 0;
    const d = await res.json();
    const val = d.rates?.[to];
    if (val === undefined) throw 0;
    await ctx.reply(`💱 <b>${fmtPrice(amount)} ${from}</b> = <b>${fmtPrice(val)} ${to}</b>\n<i>Курс на ${escapeHtml(d.date || "сегодня")}</i>`, { parse_mode: "HTML" });
  } catch {
    await ctx.reply("❌ Не смог конвертировать. Проверь коды валют (usd, eur, rub...).", { parse_mode: "HTML" });
  }
}

async function doPassgen(ctx, argStr) {
  let len = parseInt(String(argStr || "").trim()) || 16;
  len = Math.max(4, Math.min(64, len));
  const sets = [
    "ABCDEFGHJKLMNPQRSTUVWXYZ",
    "abcdefghijkmnpqrstuvwxyz",
    "23456789",
    "!@#$%^&*-_+=?"
  ];
  let pwd = sets.map(s => s[Math.floor(Math.random() * s.length)]).join("");
  const all = sets.join("");
  while (pwd.length < len) pwd += all[Math.floor(Math.random() * all.length)];
  pwd = pwd.split("").sort(() => Math.random() - 0.5).join("");
  try {
    await ctx.reply(`🔑 Сгенерировал пароль (${len} символов):\n<code>${pwd}</code>\n<i>Никому не показывай!</i>`, { parse_mode: "HTML" });
  } catch {}
}

async function doCountdown(ctx, argStr) {
  const m = String(argStr || "").trim().match(/^(\d{4})-(\d{2})-(\d{2})\s*(.*)$/);
  if (!m) {
    await ctx.reply("❌ Формат: <code>/countdown 2027-01-01 событие</code>", { parse_mode: "HTML" });
    return;
  }
  const target = new Date(`${m[1]}-${m[2]}-${m[3]}T00:00:00`);
  if (isNaN(target.getTime())) {
    await ctx.reply("❌ Неверная дата.", { parse_mode: "HTML" });
    return;
  }
  const days = Math.ceil((target.getTime() - Date.now()) / 86400000);
  const label = (m[4] || "событие").slice(0, 100);
  const word = (n) => {
    const a = Math.abs(n) % 10, b = Math.abs(n) % 100;
    if (a === 1 && b !== 11) return "день";
    if (a >= 2 && a <= 4 && (b < 10 || b >= 20)) return "дня";
    return "дней";
  };
  try {
    if (days > 0) await ctx.reply(`⏳ До «${escapeHtml(label)}» осталось: <b>${days} ${word(days)}</b>!`, { parse_mode: "HTML" });
    else if (days === 0) await ctx.reply(`🎉 «${escapeHtml(label)}» — <b>сегодня!</b>`, { parse_mode: "HTML" });
    else await ctx.reply(`📅 «${escapeHtml(label)}» было <b>${-days} ${word(days)}</b> назад.`, { parse_mode: "HTML" });
  } catch {}
}

const HOLIDAYS_RU = [
  ["01-01", "🎄 Новый год"], ["01-07", "⭐ Рождество"], ["02-14", "💘 День святого Валентина"],
  ["02-23", "🎖 День защитника Отечества"], ["03-08", "🌷 8 Марта"], ["04-01", "🤡 День смеха"],
  ["04-12", "🚀 День космонавтики"], ["05-01", "🌸 День весны и труда"], ["05-09", "🎖 День Победы"],
  ["06-01", "🧒 День защиты детей"], ["06-12", "🇷🇺 День России"], ["09-01", "📚 День знаний"],
  ["10-31", "🎃 Хэллоуин"], ["11-04", "🤝 День народного единства"], ["12-31", "🥂 Канун Нового года"]
];

async function doHoliday(ctx, argStr) {
  void argStr;
  try {
    const now = new Date();
    const year = now.getFullYear();
    let best = null;
    for (let yOff = 0; yOff <= 1 && !best; yOff++) {
      for (const [md, name] of HOLIDAYS_RU) {
        const d = new Date(`${year + yOff}-${md}T00:00:00`);
        const days = Math.ceil((d.getTime() - now.getTime()) / 86400000);
        if (days >= 0 && (!best || days < best.days)) best = { days, name };
      }
    }
    if (!best) throw 0;
    await ctx.reply(best.days === 0 ? `🎉 <b>${best.name}</b> — сегодня! Отмечаем!` : `📅 Ближайший праздник: <b>${best.name}</b> — через <b>${best.days} дн.</b>`, { parse_mode: "HTML" });
  } catch {
    await ctx.reply("❌ Не смог посчитать праздники.", { parse_mode: "HTML" });
  }
}

