const HANGMAN_STATE = new Map();
const ANAGRAM_STATE = new Map();

function hangRender(st) {
  const word = st.word.split("").map(ch => st.open.has(ch) ? ch : "_").join(" ");
  const art = HANGMAN_STAGES[st.miss].replace(/```/g, "").trim();
  return `<pre>${art}</pre>\nСлово: <code>${word}</code>\nОшибки: ${st.miss}/6 | Угаданные: ${[...st.open].join(", ") || "—"}\n<i>Буква: /hangman а</i>`;
}

function shuffleWord(w) {
  const a = w.split("");
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  const s = a.join("");
  return s === w ? shuffleWord(w) : s;
}

async function doMock(ctx, argStr) {
  const t = String(argStr || "").trim().slice(0, 300);
  if (!t) {
    await ctx.reply("❌ Формат: <code>/mock какой-то текст</code>", { parse_mode: "HTML" });
    return;
  }
  let out = "";
  let up = Math.random() < 0.5;
  for (const ch of t) {
    if (/[a-zA-Zа-яА-ЯёЁ]/.test(ch)) { out += up ? ch.toUpperCase() : ch.toLowerCase(); up = !up; }
    else out += ch;
  }
  try { await ctx.reply(`🤪 <i>${escapeHtml(out)}</i>`, { parse_mode: "HTML" }); } catch {}
}

async function doReverse(ctx, argStr) {
  const t = String(argStr || "").trim().slice(0, 300);
  if (!t) {
    await ctx.reply("❌ Формат: <code>/reverse какой-то текст</code>", { parse_mode: "HTML" });
    return;
  }
  try { await ctx.reply(`🔁 <i>${escapeHtml(t.split("").reverse().join(""))}</i>`, { parse_mode: "HTML" }); } catch {}
}

async function doShout(ctx, argStr) {
  const t = String(argStr || "").trim().slice(0, 20);
  if (!t) {
    await ctx.reply("❌ Формат: <code>/shout текст</code> (до 20 символов)", { parse_mode: "HTML" });
    return;
  }
  const lines = t.split("").map(ch => {
    const big = [
      " " + ch + ch + ch + " ",
      ch + "   " + ch,
      ch + "   " + ch,
      ch + ch + ch + ch,
      ch + "   " + ch,
      ch + "   " + ch,
      " " + ch + ch + ch + " "
    ];
    return big;
  });
  let out = "<pre>\n";
  for (let r = 0; r < 7; r++) out += lines.map(l => l[r]).join("  ") + "\n";
  out += "</pre>";
  try { await ctx.reply(`📢 ${out}`, { parse_mode: "HTML" }); } catch {}
}

