async function doStory(ctx, argStr) {
  const n = argStr ? Math.max(1, Math.min(10, parseInt(argStr) || 3)) : 3;
  let text = "";
  for (let i = 0; i < n; i++) {
    text += `${i + 1}. ${pickRandom(STORY_OPENERS)}\n   ${pickRandom(STORY_MIDDLES)}\n   ${pickRandom(STORY_TWISTS)}\n\n`;
  }
  await ctx.reply(`📖 <b>Мини-история на ${n} частей</b>\n───────────────────────\n${escapeHtml(text)}`, { parse_mode: "HTML" });
}

