async function getBusinessConnForOwner(env, ownerId, preferredConnId = null) {
  if (preferredConnId) return preferredConnId;
  try {
    const cRow = await env.DB.prepare("SELECT connection_id FROM connections WHERE user_id = ? AND (is_active = 1 OR is_active IS NULL) ORDER BY connected_at DESC LIMIT 1").bind(ownerId).first();
    return cRow?.connection_id || null;
  } catch { return null; }
}

async function getUserState(env, userId) {
  try {
    const row = await env.DB.prepare("SELECT state FROM user_states WHERE user_id = ?").bind(userId).first();
    return row?.state || null;
  } catch { return null; }
}

async function setUserState(env, userId, state) {
  try {
    const now = Math.floor(Date.now() / 1000);
    if (!state) {
      await env.DB.prepare("DELETE FROM user_states WHERE user_id = ?").bind(userId).run();
    } else {
      await env.DB.prepare(
        "INSERT INTO user_states (user_id, state, updated_at) VALUES (?, ?, ?) ON CONFLICT(user_id) DO UPDATE SET state = excluded.state, updated_at = excluded.updated_at"
      ).bind(userId, state, now).run();
    }
  } catch {}
}

