            report += `👤 <b>${escapeHtml(e.full_name)}</b> [${time}]\n❌ <i>${escapeHtml(e.old_text) || "[Пусто]"}</i>\n✅ <b>${escapeHtml(e.new_text) || "[Пусто]"}</b>\n\n`;
