                await env.DB.prepare("INSERT INTO xp (chat_id, user_id, user_name, xp, msg_count, updated_at) VALUES (?, ?, ?, ?, 1, ?) ON CONFLICT(chat_id, user_id) DO UPDATE SET xp = xp + 10, user_name = excluded.user_name, updated_at = excluded.updated_at")
                  .bind(ctx.chat.id, groupSenderId, qn.slice(0, 100), (lr?.xp || 0) + 10, Math.floor(Date.now() / 1000)).run();
