        for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
        const pct = h % 101;
        const verdict = pct >= 90 ? "💍 Идеальная пара! Срочно в ЗАГС!" : pct >= 70 ? "❤️‍🔥 Очень горячо! Всё получится!" : pct >= 50 ? "💕 Неплохой шанс, работайте над этим!" : pct >= 30 ? "🤔 Сложно... но чудеса бывают!" : pct >= 10 ? "🧊 Холодно. Лучше дружить." : "💔 Полный провал. Беги!";
        const bar = "❤️".repeat(Math.round(pct / 10)) + "🤍".repeat(10 - Math.round(pct / 10));
        try { await ctx.reply(`💘 <b>Совместимость</b>\n${escapeHtml(a)} + ${escapeHtml(b)}\n${bar}\n<b>${pct}%</b>\n<i>${verdict}</i>`, { parse_mode: "HTML" }); } catch {}
