          try {
            await env.DB.prepare("INSERT OR REPLACE INTO shields (chat_id, user_id, until_at) VALUES (?, ?, ?)").bind(ctx.chat.id, groupSenderId, Math.floor(Date.now() / 1000) + 86400).run();
          } catch {}
          try { await ctx.reply(`🛡 <b>${escapeHtml(gnm)}</b> купил(а) щит! Ограбления не страшны 24 часа.`, { parse_mode: "HTML" }); } catch {}
