          await env.DB.prepare("INSERT OR IGNORE INTO lotto_entries (chat_id, user_id, user_name, created_at) VALUES (?, ?, ?, ?)").bind(ctx.chat.id, groupSenderId, gnm.slice(0, 100), Math.floor(Date.now() / 1000)).run().catch(() => {});
          try { await ctx.reply(`🎰 Билет куплен! Розыгрыш лотереи в 21:00 МСК.`, { parse_mode: "HTML" }); } catch {}
