      if (cmdWord === "/closeticket") {
        if (!(await canModGroup(ctx.chat.id, groupSenderId))) { try { await ctx.reply("⛔ Только админы чата."); } catch {} return; }
        const id = parseInt((cmdArg.split(" ")[0] || ""));
        const res = await env.DB.prepare("UPDATE tickets SET status = 'closed', closed_at = ? WHERE id = ? AND chat_id = ?").bind(Math.floor(Date.now() / 1000), id, ctx.chat.id).run().catch(() => null);
        try { await ctx.reply(res?.meta?.changes ? `✅ Тикет #${id} закрыт.` : "❌ Тикет не найден."); } catch {}
        return;
      }
      const text = cmdArg.trim().slice(0, 500);
