  if (txt === "/menu") {
    await showMenuScreen(ctx);
    if (!(await hasBusinessConnection(env, senderId, bot))) {
      const uname = bot.botInfo?.username || "eldevcreatorrubot";
      try { await ctx.reply(`⚠️ <b>Business не подключён</b> — слежка и сохранения не работают.\n\n/connect — инструкция за 2 минуты.`, { parse_mode: "HTML", reply_markup: getConnectKeyboard() }); } catch {}
    }
    return;
  }

  if (txt === "/beta") {
    if (!ROOT_ADMINS.includes(senderId)) return ctx.reply("⛔ Недостаточно прав.");
    const rows = await env.DB.prepare("SELECT * FROM beta_applications WHERE status = 'pending' ORDER BY applied_at DESC LIMIT 20").all().catch(() => ({ results: [] }));
    if (!rows.results || rows.results.length === 0) return ctx.reply("📭 Нет заявок на рассмотрении.");
    for (const a of rows.results) {
      const kb = new InlineKeyboard()
        .text("✅ Одобрить", `beta_approve_${a.user_id}`).text("🚫 Отклонить", `beta_decline_${a.user_id}`);
      await ctx.reply(
        `🆕 <b>Заявка:</b> ${escapeHtml(a.full_name)} (@${escapeHtml(a.username) || "нет"}) — <code>${a.user_id}</code>\n💬 <i>${escapeHtml(a.reason) || "(нет текста)"}</i>`,
        { parse_mode: "HTML", reply_markup: kb }
      );
    }
    return;
  }
  if (txt === "/fun") {
    return ctx.reply(getFunMenuText(), { parse_mode: "HTML", reply_markup: getFunMenuKeyboard() });
  }
  if (/^@[\w]+(\s|$)/.test(txt)) {
    const qm = txt.replace(/^@[\w]+\s*/, "").trim();
    if (qm) {
      const ROAST_ON_ownerId = await aiRoastEnabled(env, ownerId);
      const think = await sendThinking(ctx, `🧠 <i>ELDEVCREATOR RU AI ищет в вебе и думает...</i>`);
      try {
        const answer = await aiSmart(env, qm, { ownerId: ownerId, chatId: ctx.chat.id, preferred: await getAiPreferred(env, ownerId) , extraSystem: ROAST_ON_ownerId ? ROAST_SYSTEM : "", extraUser: ROAST_ON_ownerId ? buildRoastPrompt(qm) : "" });
        await answerThinking(ctx, think, `🧠 <b>ELDEVCREATOR RU AI:</b>\n───────────────────────\n${answer}`);
        return;
      } catch (e) {
        await answerThinking(ctx, think, `❌ Ошибка нейросети: ${escapeHtml(e.message)}`);
        return;
      }
    }
  }

  if (txt === "/ai" || txt.startsWith("/ai ")) {
    const question = txt.replace("/ai", "").trim();
    if (!question) {
      return ctx.reply(getAiMenuText(), { parse_mode: "HTML", reply_markup: getAiMenuKeyboard() });
    }
    const site = urlLooksLikeSite(question);
    if (site) {
      let probe = null;
      try { probe = await withTimeout(fetchPageText(site, 8000), 15000, null); }
      catch (e) { probe = { url: site, error: String(e && e.message || e).slice(0, 120) }; }
      if (!probe || probe.error) {
        const why = probe ? probe.error : "неизвестно";
        let links = "";
        try {
          const res = await withTimeout(searxSearch(siteNameOnly(question).slice(0, 120)), 10000, []);
          if (res && res.length) {
            links = "\n\n<b>Что нашлось в поиске:</b>\n" + res.slice(0, 5).map((r) =>
              "• <a href=\"" + escapeHtml(String(r.url || "")) + "\">" + escapeHtml(String(r.title || r.url)) + "</a>"
            ).join("\n");
          }
        } catch {}
        const gateText =
          `🔍 <b>Не смог открыть ${escapeHtml(site)}</b>\n` +
          `Причина: <code>${escapeHtml(String(why).slice(0, 120))}</code>\n\n` +
          `<i>Страницу я не видел, поэтому рассказывать о её содержимом не буду — иначе просто выдумаю.</i>` +
          links +
          `\n\n<i>Если адрес верный — проверь, что домен открывается в браузере, и назови его ещё раз.</i>`;
        // never let this path end in silence
        try {
          return await ctx.reply(gateText, { parse_mode: "HTML", link_preview_options: { is_disabled: true } });
        } catch (e1) {
          console.error("ai site gate html send failed:", e1 && e1.message);
          try {
            return await ctx.reply(
              "🔍 Не смог открыть " + site + "\nПричина: " + String(why).slice(0, 120) +
              "\n\nСтраницу я не видел, поэтому о её содержимом рассказывать не буду." + links
            );
          } catch (e2) {
            console.error("ai site gate plain send failed:", e2 && e2.message);
            return;
          }
        }
      }
    }
    // Fast path: a plain "скинь музыку ..." must not wait for the model at all.
    const quickMusic = guessMusicCommand(question);
    if (quickMusic) {
      try {
        const t = await sendThinking(ctx, `🎧 <i>Нахожу трек...</i>`);
        await answerThinking(ctx, t, `⚡️ <b>Выполняю:</b> <code>${escapeHtml(quickMusic)}</code>`);
        await runAiCommand(ctx, env, bot, quickMusic);
      } catch (e) {
        console.error("ai quick music failed:", e.message);
      }
      return;
    }
    const think = await sendThinking(ctx, `🧠 <i>ELDEVCREATOR RU AI ищет в вебе и думает...</i>`);
    try {
      const fixed = aiIdentityAnswer(question, senderId);
      if (fixed) {
        await answerThinking(ctx, think, `🧠 <b>ELDEVCREATOR RU AI:</b>\n───────────────────────\n${fixed}`);
        return;
      }
      const mem = aiMemGet(ownerId, senderId);
      const memText = mem.length
        ? "\n\nИСТОРИЯ ДИАЛОГА С ТОБОЙ:\n" + mem.slice(-8).map((m) => (m.role === "user" ? "Ты: " : "Я: ") + String(m.content).slice(0, 400)).join("\n")
        : "";
      const wantsRoast = wantsRoastRequest(question);
      const ROAST_ON_ai = wantsRoast && (await aiRoastEnabled(env, ownerId));
      const answer = await withTimeout(aiSmart(env, question, {
        ownerId,
        chatId: ctx.chat.id,
        preferred: await getAiPreferred(env, ownerId),
        askerId: senderId,
        extraSystem: ROAST_ON_ai ? ROAST_SYSTEM : "",
        extraUser: (ROAST_ON_ai ? buildRoastPrompt(question, {
          name: isRootId(senderId) ? OWNER_PROFILE.nickname : "",
          style: roastStyleHint(question)
        }) : "") + memText
      }), 20000, "");
      aiMemPush(ownerId, senderId, "user", question);
      aiMemPush(ownerId, senderId, "assistant", String(answer).slice(0, 2000));
      const body = String(answer || "").trim();
      if (!body) {
        await answerThinking(ctx, think, `🤔 <b>Нейросеть не дала ответ.</b>\n<i>Попробуй переформулировать или добавь деталей.</i>`);
        return;
      }
      // strip the machine instruction before showing the text
      const shown = body.replace(AI_RUN_RE, "").replace(/\n{3,}/g, "\n\n").trim() || body;
      await answerThinking(ctx, think, `🧠 <b>ELDEVCREATOR RU AI:</b>\n───────────────────────\n${shown}\n\n<i>Помню контекст — продолжай вопросом.</i>`);

      // the AI can now actually run a command instead of only naming it
      let run = extractAiRunCommand(body);
      // fallback: a plain "найди музыку ..." must still deliver a track
      if (!run) run = guessMusicCommand(question);
      if (run) {
        const head = shown.split("\n")[0].slice(0, 120);
        await answerThinking(ctx, null, `⚡️ <b>Выполняю:</b> <code>${escapeHtml(run)}</code>${head ? `\n<i>${escapeHtml(head)}</i>` : ""}`);
        try {
          await runAiCommand(ctx, env, bot, run);
        } catch (e) {
          console.error("ai command exec failed:", e.message);
          try { await ctx.reply(`❌ Не смог выполнить <code>${escapeHtml(run)}</code>: ${escapeHtml(String(e.message).slice(0, 150))}`, { parse_mode: "HTML" }); } catch {}
        }
      }
      return;
    } catch (e) {
      await answerThinking(ctx, think, `❌ Ошибка нейросети: ${escapeHtml(e.message)}`);
      return;
    }
  }

  if (txt === "/forget") {
    aiMemClear(ownerId, senderId);
    return ctx.reply(`🧠 Память диалога очищена. Начинаем с чистого листа!`, { parse_mode: "HTML" });
  }

  if (txt === "/model" || txt.startsWith("/model ")) {
    if (!ROOT_ADMINS.includes(senderId)) return;
    const arg = (txt.split(" ")[1] || "").toLowerCase();
    if (!arg) {
      const cur = await getAiPreferred(env, ownerId);
      return ctx.reply(
        `🧠 <b>Модель нейросети</b>\n───────────────────────\nСейчас: <b>${cur ? aiModelShort(cur) : "авто"}</b>\n\nСначала всегда идёт бесплатный Pollinations (нейроны не тратит), дальше — выбранная:\n• <code>/model kimi</code> — самая умная (оживёт на платном тарифе)\n• <code>/model mistral</code> — баланс (работает на Free)\n• <code>/model llama</code> — лёгкая и быстрая\n• <code>/model auto</code> — авторежим`,
        { parse_mode: "HTML" }
      );
    }
    if (arg !== "auto" && !AI_MODEL_KEYS[arg]) return ctx.reply("❌ Варианты: <code>/model kimi|mistral|llama|auto</code>", { parse_mode: "HTML" });
    await env.DB.prepare("UPDATE settings SET ai_model = ? WHERE user_id = ?").bind(arg === "auto" ? null : AI_MODEL_KEYS[arg], ownerId).run().catch(() => {});
    return ctx.reply(`🧠 Модель переключена: <b>${arg}</b>`, { parse_mode: "HTML" });
  }

  if (txt === "/autotext" || txt.startsWith("/autotext ")) {
    const topic = txt.replace("/autotext", "").trim();
    if (!topic) {
      await setUserState(env, senderId, "await_ai_autotext");
      return ctx.reply(`✍️ Опиши тему/настроение следующим сообщением — придумаю и сохраню как автоответчик.`, { parse_mode: "HTML", reply_markup: getCancelKeyboard() });
    }
    await ctx.reply(`✍️ <i>Придумываю...</i>`, { parse_mode: "HTML" });
    try {
      const t = await aiShort(env,
        "Придумай короткий текст автоответчика для Telegram на заданную тему/настроение (1-3 предложения). Верни ТОЛЬКО сам текст, без пояснений.",
        topic, 600);
      await env.DB.prepare("UPDATE settings SET custom_reply = ? WHERE user_id = ?").bind(t, ownerId).run().catch(() => {});
      return ctx.reply(`✅ <b>Готово и сохранено как автоответчик:</b>\n«${escapeHtml(t)}»`, { parse_mode: "HTML" });
    } catch (e) {
      return ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
    }
  }

  if (txt.startsWith("/rewrite")) {
    const src = txt.replace("/rewrite", "").trim();
    if (!src) return ctx.reply("❌ Формат: <code>/rewrite твой текст</code>", { parse_mode: "HTML" });
    await ctx.reply(`🔁 <i>Переписываю...</i>`, { parse_mode: "HTML" });
    try {
      const t = await aiShort(env,
        "Перепиши сообщение пользователя в трёх вариантах: 1) деловой, 2) дружелюбный, 3) короткий. Только пронумерованные варианты, без вступлений.",
        src, 2000);
      return ctx.reply(`🔁 <b>Варианты:</b>\n───────────────────────\n${escapeHtml(t)}`, { parse_mode: "HTML" });
    } catch (e) {
      return ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
    }
  }

  if (txt.startsWith("/style")) {
    const arg = txt.split(" ")[1];
    if (!arg) return ctx.reply("❌ Формат: <code>/style @ник</code>", { parse_mode: "HTML" });
    const target = await resolveTargetUser(env, ownerId, arg);
    if (!target) return ctx.reply("❌ Контакт не найден.");
    const rows = await env.DB.prepare("SELECT full_name, text, media_type FROM messages WHERE owner_id = ? AND (chat_id = ? OR user_id = ?) AND is_outgoing = 0 ORDER BY sent_at DESC LIMIT 30").bind(ownerId, target.user_id, target.user_id).all().catch(() => ({ results: [] }));
    if (!rows.results || rows.results.length === 0) return ctx.reply(`❌ Нет сообщений от ${escapeHtml(target.full_name)} для анализа.`, { parse_mode: "HTML" });
    await ctx.reply(`🎭 <i>Разбираю стиль...</i>`, { parse_mode: "HTML" });
    try {
      const log = rows.results.reverse().map(m => `${m.full_name}: ${m.text || `[${m.media_type}]`}`).join("\n");
      const t = await aiShort(env,
        "Проанализируй стиль общения человека по логу его сообщений: формальность, длина, эмодзи, темы, эмоциональность. Затем дай 3 коротких совета, как лучше ему отвечать. Структурируй ответ.",
        log.slice(0, 4000), 2500);
      return ctx.reply(`🎭 <b>Стиль: ${escapeHtml(target.full_name)}</b>\n───────────────────────\n${escapeHtml(t)}`, { parse_mode: "HTML" });
    } catch (e) {
      return ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
    }
  }

  if (txt.startsWith("/tr ")) {
    const parts = txt.split(" ").filter(Boolean);
    await doTranslate(ctx, env, parts[1] || "", parts.slice(2).join(" "));
    return;
  }

  if (txt === "/myid") {
    return ctx.reply(`🆔 <b>Твои ID</b>\n───────────────────────\n👤 Ты: <code>${senderId}</code>\n💬 Чат: <code>${ctx.chat.id}</code>`, { parse_mode: "HTML" });
  }

  if (txt === "/music" || txt.startsWith("/music ")) {
    await doMusicSearch(ctx, env, txt.replace(/^\/music(?:@\S+)?/i, "").trim());
    return;
  }
  if (txt === "/radio" || txt.startsWith("/radio ")) {
    await doRadio(ctx, txt.replace("/radio", "").trim());
    return;
  }
  if (txt === "/lyrics" || txt.startsWith("/lyrics ")) {
    await doLyrics(ctx, txt.replace("/lyrics", "").trim());
    return;
  }
  if (txt === "/track" || txt.startsWith("/track ")) {
    await doTrack(ctx, txt.replace("/track", "").trim());
    return;
  }

  if (txt === "/sec" || txt.startsWith("/sec ")) {
    const key = (txt.split(" ")[1] || "").toLowerCase();
    const secs = {
      func: [getFuncMenuText(), getFuncMenuKeyboard()],
      ai: [getAiMenuText(), getAiMenuKeyboard()],
      help: [getHelpMenuText(), getHelpMenuKeyboard()],
      fun: [getFunMenuText(), getFunMenuKeyboard()],
      music: [getMusicMenuText(), getMusicMenuKeyboard()]
    };
    if (!secs[key]) {
      return ctx.reply(`📂 <b>Секции:</b> <code>/sec func|ai|help|fun|music</code>`, { parse_mode: "HTML" });
    }
    return showTextScreen(ctx, secs[key][0], secs[key][1]);
  }

function aihamStream(key) {
  const k = String(key || "random").toLowerCase();
  return AIHAM_STREAMS.find((s) => s.key === k) || AIHAM_STREAMS[0];
}

function buildAihamPrompt(streamKey, targetName, extra) {
  const st = aihamStream(streamKey);
  const who = targetName ? `Человека по имени «${targetName}».` : "Того, кто написал это сообщение.";
  return [
    "",
    "ЗАДАЧА: написать смешной троллинг-рост по-русски.",
    "",
    "СТИЛЬ: " + st.system,
    "",
    who,
    extra ? "КОНТЕКСТ ПРО ЧЕЛОВЕКА: " + extra : "",
    "",
    "ЖЁСТКИЕ ПРАВИЛА:",
    "- Это шутка между людьми в чате. Рост должен быть смешным, а не унизительно-серьёзным.",
    "- Никаких угроз, желаний смерти, упоминаний болезней, внешности в целом и реальных трагедий.",
    "- Не упоминай конкретных людей, которых тут нет, и не придумывай про него выдуманные факты о здоровье или семье.",
    "- Без морали, без извинений, без ностальгии. Чистый троллинг.",
    "- Формат: только сам текст роста, без заголовка и без объяснений.",
    "- Длина: 1-6 строк. Короче — острее.",
    "",
    "СЕЙЧАС НАПИШИ РОСТ:"
  ].filter(Boolean).join("\n");
}

async function doAiham(ctx, env, argStr, opts = {}) {
  const raw = String(argStr || "").trim();
  let rest = raw;
  let streamKey = opts.stream || "random";

  // .aiham стиль — принудительно выбранный стиль, всё остальное — цель
  const mStyle = rest.match(/^(классика|poetic|стих|pro|спорт|stream|стрим|respect|холодный|mom|мамка|hr|hr|fortune|астролог|gamer|геймер|random|рандом)\b\s*/i);
  if (mStyle) {
    const map = { "классика": "roast", "стих": "poetic", "спорт": "pro", "стрим": "stream", "холодный": "respect", "мамка": "mom", "астролог": "fortune", "геймер": "gamer", "рандом": "random" };
    streamKey = map[mStyle[1].toLowerCase()] || mStyle[1].toLowerCase();
    rest = rest.slice(mStyle[0].length).trim();
  }

  let targetName = "";
  if (opts.targetName) {
    targetName = String(opts.targetName).trim();
    if (rest) rest = "";
  } else if (rest) {
    const at = rest.match(/@[\w_]{2,32}/);
    if (at && /^@/.test(rest.trim())) {
      targetName = at[0];
      rest = rest.replace(at[0], "").trim();
    } else if (!/^@/.test(rest)) {
      targetName = rest;
      rest = "";
    }
  }

  const st = aihamStream(streamKey);
  const ask = st.key === "random" ? aihamStream(pickRandom(AIHAM_STREAMS).key) : st;

  const think = await sendThinking(ctx, `🧢 <i>AIHAM наводит на рост... (${ask.name})</i>`);
  const ownerId = Number(opts.ownerId || ctx.from?.id || 0);
  const askerId = Number(opts.askerId || ctx.from?.id || ownerId);
  let text = "";
  try {
    text = await withTimeout(aiSmart(env, buildAihamPrompt(streamKey, targetName, rest), {
      ownerId,
      askerId,
      chatId: 0,
      extraSystem: ROAST_SYSTEM
    }), 25000, "");
  } catch (e) {
    console.error("aiham failed:", e.message);
  }

  const body = String(text || "").trim();
  const out = body
    ? `🧢 <b>AIHAM • ${escapeHtml(ask.name)}</b>\n───────────────────────\n${escapeHtml(body.slice(0, 1800))}`
    : `🧢 <b>AIHAM • ${escapeHtml(ask.name)}</b>\n───────────────────────\n${escapeHtml(pickRandom(AIHAM_FALLBACKS))}\n\n<i>⚠️ Нейросеть не ответила — рост из запаса.</i>`;

  const hint = `\n\n<i>Стили: ${AIHAM_STREAMS.map((s) => s.name.split(" ")[1]).join(" • ")} — выбери: <code>.aiham стиль</code>\nЦель: <code>.aiham @ник</code> • Свой текст: <code>.aiham сюда текст</code></i>`;

  return answerThinking(ctx, think, withCredit(out + hint));
  }

  if (txt === "/joke" || txt === "/toast") {
    const isJoke = txt === "/joke";
    await ctx.reply(isJoke ? `😂 <i>Вспоминаю шутку...</i>` : `🥂 <i>Сочиняю тост...</i>`, { parse_mode: "HTML" });
    try {
      const t = await aiShort(env,
        isJoke ? "Расскажи одну короткую смешную шутку или анекдот на русском. Только текст шутки, без вступлений." : "Придумай один короткий оригинальный тост на русском. Только текст тоста, без вступлений.",
        isJoke ? "шутка" : "тост", 1000);
      return ctx.reply((isJoke ? "😂 " : "🥂 ") + t + "\n<i>🤖 ELDEVCREATOR RU AI • t.me/eldevcreator</i>");
    } catch (e) {
      const fb = isJoke ? pickRandom(INLINE_JOKES) : pickRandom(INLINE_TOASTS);
      return ctx.reply(`${isJoke ? "😂 " + escapeHtml(fb) : escapeHtml(fb)}\n<i>⚠️ Нейросеть спит — держи из запасов.</i>`, { parse_mode: "HTML" });
    }
  }

  if (txt === "/fact") {
    try {
      const t = await aiShort(env, "Расскажи один короткий интересный факт (наука, история, природа, технологии). Только факт, без вступлений.", "факт", 800);
      return ctx.reply("💡 <b>Факт дня:</b>\n" + t + "\n<i>🤖 ELDEVCREATOR RU AI • t.me/eldevcreator</i>");
    } catch (e) {
      return ctx.reply(pickRandom(INLINE_FACTS) + `\n<i>⚠️ Нейросеть спит — держи из запасов.</i>`, { parse_mode: "HTML" });
    }
  }

  if (txt === "/quiz") {
    await startQuiz(ctx, env, ownerId);
    return;
  }

  if (txt.startsWith("/reply") || txt.startsWith("/mood") || txt.startsWith("/bio") || txt.startsWith("/roast")) {
    const cmd = txt.split(" ")[0].replace("/", "");
    const rest = txt.replace("/" + cmd, "").trim().split(" ").filter(Boolean);
    const arg = rest[0] || "";
    const extra = rest.slice(1).join(" ");
    if (!arg) return ctx.reply(`❌ Формат: <code>/${cmd} @ник [контекст]</code>`, { parse_mode: "HTML" });
    const kind = { reply: "reply", mood: "mood", bio: "bio", roast: "roast" }[cmd];
    await cmdContactAi(ctx, env, ownerId, arg, kind, extra);
    return;
  }

  if (txt.startsWith("/excuse") || txt.startsWith("/dream") || txt.startsWith("/horo")) {
    const cmd = txt.split(" ")[0].replace("/", "");
    const body = txt.replace("/" + cmd, "").trim();
    const stateMap2 = { excuse: "await_ai_excuse", dream: "await_ai_dream", horo: "await_ai_horo" };
    if (!body) {
      await setUserState(env, senderId, stateMap2[cmd]);
      const hints = {
        excuse: "🤥 Опиши ситуацию следующим сообщением (например: <i>опоздал на работу</i>).",
        dream: "💤 Опиши сон следующим сообщением — истолкую.",
        horo: "♈ Пришли свой знак зодиака следующим сообщением (например: <i>лев</i>)."
      };
      return ctx.reply(hints[cmd] + "\n\n<i>/cancel — отмена</i>", { parse_mode: "HTML", reply_markup: getCancelKeyboard() });
    }
    const prompts = {
      excuse: "Придумай смешную, но правдоподобную отмазку под описанную ситуацию. 2-3 предложения, только текст.",
      dream: "Истолкуй описанный сон: значение и короткий совет. Мистично-весело, 3-5 предложений.",
      horo: "Дай гороскоп на сегодня для указанного знака зодиака: любовь, дела, совет. Коротко, по пунктам."
    };
    const titles = { excuse: "🤥 <b>Отмазка:</b>\n", dream: "💤 <b>Сонник:</b>\n", horo: "♈ <b>Гороскоп:</b>\n" };
    await ctx.reply(`<i>Думаю...</i>`, { parse_mode: "HTML" });
    try {
      const t = await aiShort(env, prompts[cmd], body, 1500);
      return ctx.reply(titles[cmd] + escapeHtml(t), { parse_mode: "HTML" });
    } catch (e) {
      if (cmd === "excuse") {
        return ctx.reply(`🤥 <b>Отмазка (из запасов):</b>\n${escapeHtml(pickRandom(EXCUSES_RU))}\n<i>⚠️ Нейросеть спит.</i>`, { parse_mode: "HTML" });
      }
      if (cmd === "dream") {
        return ctx.reply(`💤 <b>Сонник (кратко):</b>\nСон про «${escapeHtml(body.slice(0, 100))}» — к переменам! Подсознание намекает: не тяни с важным решением.\n<i>⚠️ Нейросеть спит — полное толкование позже.</i>`, { parse_mode: "HTML" });
      }
      const sign = horoSignOf(body);
      const fb = sign ? (horoDaily(sign) || HORO_FALLBACK[sign]) : null;
      if (fb) {
        return ctx.reply(`♈ <b>Гороскоп: ${escapeHtml(sign)}</b>\n${escapeHtml(fb)}\n<i>⚠️ Нейросеть спит — прогноз из запасов.</i>`, { parse_mode: "HTML" });
      }
      return ctx.reply(`❌ Ошибка нейросети: ${escapeHtml(e.message)}`, { parse_mode: "HTML" });
    }
  }

  async function runFunCommand(kind, arg) {
    if (arg) {
      const target = await resolveTargetUser(env, ownerId, arg);
      const targetId = target ? target.user_id : parseInt(arg);
      if (!targetId) return ctx.reply("❌ Не нашёл контакт. Формат: <code>/love @ник</code> или просто <code>/love</code>", { parse_mode: "HTML" });
      const connId = await getBusinessConnForOwner(env, ownerId, null);
      if (!connId) return ctx.reply("❌ Нет активного Business-подключения.", { parse_mode: "HTML" });
      await ctx.reply(`🚀 Отправляю анимацию в чат <code>${targetId}</code>...`, { parse_mode: "HTML" });
      if (kind === "love") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.love, 450);
      else if (kind === "fire") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.fire, 450);
      else if (kind === "kiss") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.kiss, 450);
      else if (kind === "hug") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.hug, 500);
      else if (kind === "party") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.party, 450);
      else if (kind === "dance") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.dance, 450);
      else if (kind === "boom") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.boom, 400);
      else if (kind === "rain") await playAnimationViaBusiness(bot, connId, targetId, FUN_FRAMES.rain, 450);
      else if (kind === "roll") {
        const n = 1 + Math.floor(Math.random() * 6);
        await playAnimationViaBusiness(bot, connId, targetId, [...FUN_FRAMES.roll_intro, `🎲 Выпало: ${n}!`], 350, { parse_mode: "HTML" });
      } else if (kind === "coin") {
        const res = Math.random() < 0.5 ? "🦅 Орёл!" : "🪙 Решка!";
        await playAnimationViaBusiness(bot, connId, targetId, [...FUN_FRAMES.coin_flip, res], 350);
      } else if (kind === "magic") {
        const ans = MAGIC_ANSWERS[Math.floor(Math.random() * MAGIC_ANSWERS.length)];
        await playAnimationViaBusiness(bot, connId, targetId, [...FUN_FRAMES.magic_intro, `🔮 ${ans}`], 350);
      }
      return;
    }
    if (kind === "love") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.love, 450, { __api: ctx.api });
    else if (kind === "fire") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.fire, 450, { __api: ctx.api });
    else if (kind === "kiss") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.kiss, 450, { __api: ctx.api });
    else if (kind === "hug") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.hug, 500, { __api: ctx.api });
    else if (kind === "party") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.party, 450, { __api: ctx.api });
    else if (kind === "dance") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.dance, 450, { __api: ctx.api });
    else if (kind === "boom") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.boom, 400, { __api: ctx.api });
    else if (kind === "rain") await playAnimationInChat(bot, ctx.chat.id, FUN_FRAMES.rain, 450, { __api: ctx.api });
    else if (kind === "roll") {
      const n = 1 + Math.floor(Math.random() * 6);
      await playAnimationInChat(bot, ctx.chat.id, [...FUN_FRAMES.roll_intro, `🎲 Выпало: <b>${n}</b>!`], 350, { parse_mode: "HTML", __api: ctx.api });
    } else if (kind === "coin") {
      const res = Math.random() < 0.5 ? "🦅 Орёл!" : "🪙 Решка!";
      await playAnimationInChat(bot, ctx.chat.id, [...FUN_FRAMES.coin_flip, res], 350, { __api: ctx.api });
    } else if (kind === "magic") {
      const ans = MAGIC_ANSWERS[Math.floor(Math.random() * MAGIC_ANSWERS.length)];
      await playAnimationInChat(bot, ctx.chat.id, [...FUN_FRAMES.magic_intro, `🔮 ${ans}`], 350, { __api: ctx.api });
    }
  }

