    if (what === "edits" || what === "all") await env.DB.prepare("UPDATE settings SET notify_edited = ? WHERE user_id = ?").bind(val, ownerId).run();
    return ctx.reply(`🔔 Готово: <b>${what}</b> → <b>${state === "on" ? "ВКЛ" : "ВЫКЛ"}</b>.`, { parse_mode: "HTML" });
